(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c20"]=[{"id":"00002723","register_sub_id":"101","register_pk":"103713","name":"小柳酒造ムロマエ","kana":"こやなぎしゅぞうむろまえ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町903-1","lat":33.29891956,"lng":130.20235198,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積47㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"41 － 0038","desc":"麹室東妻面から昭和西蔵西面に向けて屋根を架け室前空間を造る。桁行７ｍ，梁間６ｍ規模の東西棟，桟瓦葺，切妻造で，南面には桟瓦葺の土庇を付けて東寄りに入口を設ける。麹室，酒母室とともに敷地西北隅部を形成して醸造施設特有の佇まいを醸しだしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002723"},{"id":"00003480","register_sub_id":"101","register_pk":"104470","name":"天山酒造旧精米所立型水車及び水路","kana":"てんざんしゅぞうきゅうせいまいしょたてがたすいしゃおよびすいろ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町大字岩蔵1520","lat":33.31197924,"lng":130.19260173,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"コンクリート造水路延長57m、水車よりなる","structure_material":"コンクリート造水路延長57m","registered":"2003.07.01(平成15.07.01)","register_no":"41 － 0043","desc":"敷地北端に位置する旧精米所に祇園川から取水する用水路を引き入れて水車を回す。水車は鉄製の立軸型水車で，精米機の動力源となる。水車精米時代の遺構であり，酒造システムの近代化過程の一面を物語る遺産として貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003480"},{"id":"00003479","register_sub_id":"101","register_pk":"104469","name":"天山酒造昭和蔵","kana":"てんざんしゅぞうしょうわぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町大字岩蔵1520","lat":33.31158487,"lng":130.19337955,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"土蔵造2階建、瓦葺、建築面積1253㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"41 － 0042","desc":"大正蔵の東側に平行して建つ。桁行３０間，梁間７間規模で，南妻面に桁行７間，梁間４間の麹室が取り付く。北寄り桁行１２間分は多久からの移設であるが，外観上は大正蔵と同様に両妻を半寄棟形とし，腰縦板張，２段窓の長大な桁行面を東側道路沿いに見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003479"},{"id":"00003478","register_sub_id":"101","register_pk":"104468","name":"天山酒造明治蔵及び大正蔵","kana":"てんざんしゅぞうめいじぐらおよびたいしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県小城市小城町大字岩蔵1520","lat":33.31143449,"lng":130.19325841,"geo_status":"db","era":"明治初期／大正初期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階一部平屋建、瓦及びスレート葺、建築面積1716㎡","structure_material":"土蔵造2階一部平屋建","registered":"2003.07.01(平成15.07.01)","register_no":"41 － 0041","desc":"桁行８間，梁間３間，三重梁構造の明治蔵の北及び東に大正蔵がＵ字状に増築され，全体として桁行３０間，梁行１２間の大規模酒蔵となる。腰を縦板張，上部白漆喰塗壁に水切り瓦付きの窓を２段に配置し，妻を半寄棟に納めるなど特徴ある北面をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003478"},{"id":"00015266","register_sub_id":"101","register_pk":"530690","name":"戸上電機製作所本館","kana":"とがみでんきせいさくしょほんかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県佐賀市大財北町385-1他","lat":33.26370278,"lng":130.30405,"geo_status":"db","era":"大正14年／昭和13年・同30年代増築、令和5年改修","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造2階一部3階建、鉄板葺、建築面積518㎡","structure_material":"木造2階一部3階建","registered":"2024.12.03(令和6.12.03)","register_no":"41 - 0135","desc":"ＪＲ佐賀駅東方の市街地に位置する、配電部品製造業の本社屋。木造三階建で南正面の玄関から上へ、四本の付柱が増築の三階を越えて伸びる。一・二階は矩形窓、三階はアーチ窓を開ける。外壁は磁器タイル貼。佐賀の電気産業の発展を伝える象徴的な事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015266"},{"id":"00005684","register_sub_id":"101","register_pk":"106672","name":"中島酒造場麹室","kana":"なかしましゅぞうじょうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2714他","lat":33.09202004,"lng":130.11531116,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積37㎡","structure_material":"土蔵造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0068","desc":"仕込蔵の東に南妻を揃えて建つ。桁行３間半，梁間３間規模の土蔵造平屋建で，切妻造，桟瓦葺とする。外壁の腰部には煉瓦を張り，仕込蔵側の西面はモルタル仕上げとして南端に出入口を設けている。南面に仕込蔵と一連の瓦葺庇をつける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005684"},{"id":"00005682","register_sub_id":"101","register_pk":"106670","name":"中島酒造場仕込蔵","kana":"なかしましゅぞうじょうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2714他","lat":33.09210027,"lng":130.11516712,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積409㎡、煙突付","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0066","desc":"主屋の南背後，釜場に接続して建つ土蔵造２階建，切妻造，桟瓦葺の南北棟２棟で，西棟が桁行１１間半，梁間４間半，東棟が桁行１１間，梁間４間で，２棟の間の壁を撤去して使用している。南面には東の麹室と一連で瓦葺庇がつく。西棟の南北に煉瓦造煙突が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005682"},{"id":"00005685","register_sub_id":"101","register_pk":"106673","name":"中島酒造場土蔵","kana":"なかしましゅぞうじょうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2714他","lat":33.0927035,"lng":130.11515923,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積203㎡","structure_material":"土蔵造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0069","desc":"多良往還を挟んで主屋の向いに建つ土蔵造平屋建で，切妻造，桟瓦葺とする。街路からやや後退して建つ。南妻に戸口を設け瓦葺庇を架ける。桁行１０間半，梁間３間の南北棟，桁行４間半，梁間３間半の南北棟，桁行３間半，梁間３間半の東西棟の３棟が連続する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005685"},{"id":"00005683","register_sub_id":"101","register_pk":"106671","name":"中島酒造場西蔵","kana":"なかしましゅぞうじょうにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市浜町乙2714他","lat":33.09212563,"lng":130.11499095,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積169㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0067","desc":"主屋の南，仕込蔵の西に並んで建つ土蔵造２階建の貯蔵庫。桁行６間，梁間６間の南北棟で，屋根は切妻造，桟瓦葺とする。外壁は白漆喰塗で，西壁の腰部を煉瓦貼とし，一部鉄板で覆っている。小屋組は束立の和小屋である。浜川側からの景観の一要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005683"},{"id":"00004468","register_sub_id":"101","register_pk":"105458","name":"富久千代酒造一号蔵","kana":"ふくちよしゅぞういちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市浜町1254-1","lat":33.09375397,"lng":130.11439492,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、瓦葺、建築面積522㎡","structure_material":"木造2階建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0045","desc":"敷地西側のほぼ中央に東西棟で建つ。桁行１４間梁間８間規模，寄棟造，桟瓦葺の２階建酒蔵で，南面に２間半幅の下屋を付ける。内部は，１階が仕込蔵で，西側を槽場，２階を倉庫，下屋を製品倉庫に充てる。外壁は縦板張とし，敷地西辺の酒蔵景観の中核となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004468"},{"id":"00004470","register_sub_id":"101","register_pk":"105460","name":"富久千代酒造麹室","kana":"ふくちよしゅぞうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市浜町1254-1","lat":33.09398149,"lng":130.114487,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積154㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0047","desc":"敷地西北隅，一号蔵の北方に位置し，敷地西辺に沿って南北棟で建つ。桁行８間梁間３間規模，切妻造，桟瓦葺の木造平屋建で，内部には麹室を２室設け，東面に下屋を差し掛ける。西側街路沿い酒蔵景観の形成要素で，外壁は他の酒蔵同様に焼杉の縦板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004470"},{"id":"00004469","register_sub_id":"101","register_pk":"105459","name":"富久千代酒造精米所","kana":"ふくちよしゅぞうせいまいしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市浜町1254-1","lat":33.09372,"lng":130.11479107,"geo_status":"db","era":"大正10頃","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積128㎡","structure_material":"木造平屋建","registered":"2004.11.08(平成16.11.08)","register_no":"41 － 0046","desc":"一号蔵東妻面北寄りに西妻面を接して建つ。東西棟，切妻造，桟瓦葺の木造平屋建で，桁行９間半梁間３間の平面規模とし，小屋組は登り梁と二重梁を交互に架ける。外壁は一号蔵と同様に焼杉縦板張とする。造り酒屋の酒造場に欠くことのできない施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004469"},{"id":"00000230","register_sub_id":"101","register_pk":"101220","name":"村岡総本舗羊羹資料館","kana":"むらおかそうほんぽようかんしりょうかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"佐賀県","address":"佐賀県小城市小城町861","lat":33.30135525,"lng":130.20428018,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造2階建，建築面積72㎡","structure_material":"木造2階建","registered":"1997.06.12(平成9.06.12)","register_no":"41 － 0002","desc":"砂糖貯蔵庫として建てられ、昭和59年の改装によって資料館となった。躯体は木造で、寄棟の屋根、和小屋の小屋組とも完全な和風建築であるが、ファサードは煉瓦とタイルによる洋風の意匠となっており、その特徴的な外観で広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000230"},{"id":"00005671","register_sub_id":"101","register_pk":"106659","name":"矢野酒造旧精米所","kana":"やのしゅぞうきゅうせいまいしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.11293918,"lng":130.0937481,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積127㎡","structure_material":"木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0055","desc":"街路に面して主屋の南に並ぶ木造平屋建の東西棟。桁行９間，梁間３間の切妻造，桟瓦葺で，屋根西寄りに越屋根を載せる。正面に瓦葺庇がつく。外壁は白漆喰塗で，正面の妻壁は下見板張とする。内部は天井を張らずに小屋組を現しとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005671"},{"id":"00005675","register_sub_id":"101","register_pk":"106663","name":"矢野酒造麹室","kana":"やのしゅぞうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.11283736,"lng":130.09294443,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"煉瓦造及び木造平屋建、瓦葺、建築面積81㎡","structure_material":"煉瓦造及び木造平屋建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0059","desc":"敷地の西端，西蔵の南に接続する煉瓦造及び木造平屋建。桁行６間，梁間３間の南北棟で，煉瓦壁の上部に竪羽目板張の壁を立ち上げ，切妻造桟瓦葺の屋根を架けている。内部は北から２間位置に間仕切を設けて前室とし，内壁は煉瓦壁にモルタルを塗る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005675"},{"id":"00005673","register_sub_id":"101","register_pk":"106661","name":"矢野酒造中蔵","kana":"やのしゅぞうなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.11315926,"lng":130.09318816,"geo_status":"db","era":"明治39／昭和20代増築","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積389㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0057","desc":"東蔵の西に並んで建つ木造２階建。桁行１４間，梁間６間，切妻造桟瓦葺の南北棟で，東蔵と戸口で接続している。仕込蔵として建設されたが，現在は貯蔵庫として用いられている。昭和２０年代に南端２間を増築した。外壁は白漆喰塗で南側妻壁に鉄板を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005673"},{"id":"00005674","register_sub_id":"101","register_pk":"106662","name":"矢野酒造西蔵","kana":"やのしゅぞうにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.11319045,"lng":130.09305116,"geo_status":"db","era":"大正10","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積204㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0058","desc":"敷地の西端，中蔵の西に並んで建つ木造２階建。桁行９間，梁間３間の切妻造，桟瓦葺の南北棟で，外壁を鉄板張とする。東側外壁は撤去され，中蔵と壁を共有する。南側に接続する桁行５間の貯蔵庫は２階が蔵人部屋であった。敷地西からの景観の主要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005674"},{"id":"00005672","register_sub_id":"101","register_pk":"106660","name":"矢野酒造東蔵","kana":"やのしゅぞうひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"佐賀県","address":"佐賀県鹿島市大字高津原字一本杉3903-1他","lat":33.11312926,"lng":130.09333145,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積281㎡","structure_material":"土蔵造2階建","registered":"2006.08.03(平成18.08.03)","register_no":"41 － 0056","desc":"敷地のほぼ中央，離れの西に位置する木造２階建。桁行１１間，梁間５間，切妻造，桟瓦葺の南北棟で，仕込蔵として建設され，現在は製品庫である。東面戸口の北側に検査室と分析室が付属。外壁は白漆喰塗で，腰を下見板張とする。小屋組は束立ちの和小屋である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005672"},{"id":"00005386","register_sub_id":"101","register_pk":"106374","name":"今里酒造洗い場","kana":"いまざとしゅぞうあらいば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町宿郷596","lat":33.13667773,"lng":129.89645004,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、鉄板葺、建築面積266㎡","structure_material":"木造平屋建","registered":"2006.03.02(平成18.03.02)","register_no":"42 － 0054","desc":"本蔵及び中蔵の北方に位置し東西棟で建つ。桁行１１間，梁間４間規模の切妻造，平屋建で，西に試験室を張り出し，南面から本蔵及び中蔵の北面に下屋を架ける。小屋組はキングポストトラスで，棟に煙出しを設ける。酒造場の発展を物語る施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005386"},{"id":"00005385","register_sub_id":"101","register_pk":"106373","name":"今里酒造新蔵","kana":"いまざとしゅぞうしんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町宿郷641","lat":33.13644963,"lng":129.89623214,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、瓦葺、建築面積491㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"42 － 0053","desc":"中蔵の西に接して南北棟で建つ。酒蔵の解体材を用いて建設と伝える。桁行１８間，梁間６間規模の総２階建で，棟通り３間毎に丸柱を建て，４重梁の小屋を組む。当酒造場では最も規模が大きく，建ちも高く，他の切妻造と異なり寄棟造であることで際立った存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005385"},{"id":"00005387","register_sub_id":"101","register_pk":"106375","name":"今里酒造製品置き場","kana":"いまざとしゅぞうせいひんおきば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県東彼杵郡波佐見町宿郷596","lat":33.13635625,"lng":129.89634859,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積95㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"42 － 0055","desc":"中蔵の南妻面及び新蔵東面南寄りに接して建つ。桁行５間，梁間３間規模，南北棟の切妻造２階建で，東面に下屋を差し掛ける。もと玄米置き場で，２階北側の１５畳半は杜氏部屋とする。小規模な建造物ではあるが，酒造場に欠くことのできない施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005387"},{"id":"00005384","register_sub_id":"101","register_pk":"106372","name":"今里酒造中蔵","kana":"いまざとしゅぞうなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県東彼杵郡波佐見町宿郷596","lat":33.13651777,"lng":129.89637634,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積319㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"42 － 0052","desc":"本蔵の西に並列して建つ。桁行１２間梁間４間半規模の切妻造２階建で，小屋組は二重梁と登り梁を交互に用い，東側の本蔵との間の２間幅の通路は東面の屋根を葺き下ろす。本蔵とともに創業時に近い酒造施設で，明治１２年の大火でも焼失を免れている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005384"},{"id":"00005383","register_sub_id":"101","register_pk":"106371","name":"今里酒造本蔵","kana":"いまざとしゅぞうほんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県東彼杵郡波佐見町宿郷596","lat":33.13651625,"lng":129.896515,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積283㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"42 － 0051","desc":"店舗土間の北端部を蔵前とし，土間北方に接して南北棟で建つ。桁行１２間，梁間６間，切妻造の酒蔵で，中央部に２階を設ける。小屋組は２間毎に二重梁を架け，その間に登り梁を入れる。酒造場の中心施設で，主屋，中蔵とともに川沿いに雄大な景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005383"},{"id":"00002733","register_sub_id":"101","register_pk":"103723","name":"梅ヶ枝酒造旧北蔵","kana":"うめがえしゅぞうきゅうきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.090057,"lng":129.815048,"geo_status":"db","era":"明治期／昭和35頃移築","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造平屋建、瓦葺、建築面積147㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0018","desc":"住居（離れ）の北方に建つ。もと精米所で，移築前は貯蔵蔵の北方に所在した。桁行１９．７ｍ，梁間６．７ｍ規模，切妻造，桟瓦葺の２階建で，南東部に桁行７．９ｍ，幅１．９ｍの張り出しを設ける。規模が大きく，梅ヶ枝酒造発展期を物語る遺構のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002733"},{"id":"00002731","register_sub_id":"101","register_pk":"103721","name":"梅ヶ枝酒造旧仕込蔵","kana":"うめがえしゅぞうきゅうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.08992,"lng":129.814514,"geo_status":"db","era":"江戸末期／明治後期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造平屋建、瓦葺、建築面積264㎡","structure_material":"土蔵造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0016","desc":"敷地の西南隅部に位置し，「旧むろ」の西に接して建つ。桁行１８ｍ，梁間１１．９ｍ規模，東西棟，桟瓦葺，切妻造の平屋建で，北西部を２度にわたり増築し，内部では間内柱と和小屋をブレースで補強している。規模が大きく，造り酒屋の中核的施設になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002731"},{"id":"00002730","register_sub_id":"101","register_pk":"103720","name":"梅ヶ枝酒造旧むろ","kana":"うめがえしゅぞうきゅうむろ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"江戸","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.089828,"lng":129.814682,"geo_status":"db","era":"江戸末期／明治後期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"煉瓦及び木造平屋建、瓦葺、建築面積74㎡","structure_material":"煉瓦及び木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0015","desc":"瓶詰所２階建部の西に建つ。桁行８．３ｍ，梁間８．９ｍ規模の東西棟，桟瓦葺，切妻造建家の内部に特徴ある積み方の煉瓦造ムロを造る。外観上では，西に隣接する旧仕込蔵の屋根と一体化されており，南面に造り酒屋特有の路地的佇まいをつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002730"},{"id":"00002732","register_sub_id":"101","register_pk":"103722","name":"梅ヶ枝酒造貯蔵蔵","kana":"うめがえしゅぞうちょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.090027,"lng":129.814743,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"煉瓦及び土蔵造2階建、瓦葺、建築面積141㎡","structure_material":"煉瓦及び土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0017","desc":"主屋の西方，旧仕込蔵の北方に建つ。桁行１８．３ｍ，梁間７．７ｍ規模，東西棟，桟瓦葺，切妻造，２階建で，腰高までのイギリス積煉瓦造基礎の上に木軸を組む。両妻面に入口を設け，１階西端部に酒絞り器を据えて槽場とする。中心的醸造施設のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002732"},{"id":"00002729","register_sub_id":"101","register_pk":"103719","name":"梅ヶ枝酒造瓶詰所","kana":"うめがえしゅぞうびんづめじょ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長崎県","address":"長崎県佐世保市城間町317","lat":33.089775,"lng":129.814789,"geo_status":"db","era":"江戸末期／明治後期改造","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積125㎡","structure_material":"土蔵造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"42 － 0014","desc":"主屋南面下屋部（もと釜場）の南方に位置する。桁行９．４ｍ梁間６．４ｍ，南北棟，切妻造の平屋建部と，桁行１１．５ｍ梁間５．６ｍ，東西棟，切妻造の総２階建部とがＬ字形に繋がる。１階はともに土間になっており，現在は出荷の作業場に充てられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002729"},{"id":"00007412","register_sub_id":"101","register_pk":"108394","name":"加藤酒造井戸","kana":"かとうしゅぞういど","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県島原市有明町大三東戊字西川1216-1","lat":32.852177,"lng":130.331329,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"石造、面積1.5㎡","structure_material":"石造","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0075","desc":"主屋の通りニワの後方、敷地のほぼ中央に位置する。厚さ０．１８ｍの地元産の凝灰岩を、方１．２ｍ高さ０．４５ｍに相欠で組む。内部は直径１．０ｍで円筒状に堀り、深さは１０ｍを測る。酒醸造に使ったと伝える井戸である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007412"},{"id":"00007415","register_sub_id":"101","register_pk":"108397","name":"加藤酒造裏土塀","kana":"かとうしゅぞううらどべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市有明町大三東戊字西川1216-1","lat":32.85206749,"lng":130.33120243,"geo_status":"db","era":"明治前期／大正期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土塀、瓦葺、延長37m","structure_material":"土塀","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0078","desc":"主屋背面の上便所西南隅から西へ延び、隅切りとする西南角で敷地形状にあわせて北に折れる。延長３７ｍ、高さ２．４ｍで、西面の塀は低くする。いずれも石積の上を土塀とする。頂部に桟瓦を葺き、漆喰で塗り固める。東端には石積の高さに通用口を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007415"},{"id":"00007414","register_sub_id":"101","register_pk":"108396","name":"加藤酒造表土塀","kana":"かとうしゅぞうおもてどべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県島原市有明町大三東戊字西川1216-1","lat":32.85233607,"lng":130.33123196,"geo_status":"db","era":"大正期／昭和40頃改修","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土塀、瓦葺、延長16m","structure_material":"土塀","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0077","desc":"門の西から通り沿いに西へ延び、敷地西北角で南に折れる。折曲り延長１６ｍ、高さ２．４～３．４ｍ。石積上を土塀とし、頂部に桟瓦を葺き、漆喰で塗り固める。石積は高さ１．３～１．７ｍで切込み矧ぎとする。伝統的な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007414"},{"id":"00007411","register_sub_id":"101","register_pk":"108393","name":"加藤酒造店舗兼主屋","kana":"かとうしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市有明町大三東戊字西川1216-1","lat":32.852219,"lng":130.331421,"geo_status":"db","era":"明治前期／明治後期・大正期・昭和前期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、瓦葺、建築面積266㎡","structure_material":"木造平屋建","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0074","desc":"通りに北面する規模の大きい平入町家。入母屋造桟瓦葺の木造つし２階建で、西半部の棟を少し高くし、背面東寄りに角屋を付ける。内部は西寄りの土間と床上部からなり、上質なつくりになる座敷飾りを備える座敷や仏間など３室を東端に並べる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007411"},{"id":"00007413","register_sub_id":"101","register_pk":"108395","name":"加藤酒造門","kana":"かとうしゅぞうもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"長崎県","address":"長崎県島原市有明町大三東戊字西川1216-1","lat":32.85228989,"lng":130.33130761,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造、瓦葺、間口2.5m","structure_material":"木造","registered":"2008.10.23(平成20.10.23)","register_no":"42 － 0076","desc":"主屋の西、通りに北面して建つ一間薬医門。切石礎石に本柱を建て、冠木、男梁を架す。軒は一軒疎垂木。切妻造桟瓦葺で、棟は熨斗積とし、漆喰で塗り固める。間口２．５ｍで、両開の板戸を吊る。比較的規模の大きい門で、主屋とともに表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007413"},{"id":"00009681","register_sub_id":"101","register_pk":"194677","name":"旧佐世保鎮守府武庫預兵器庫","kana":"きゅうさせぼちんじゅふぶこあずかりへいきこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県佐世保市立神町23","lat":33.166577,"lng":129.70774536,"geo_status":"db","era":"明治32／明治36増築","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"煉瓦造2階建、スレート葺、建築面積646㎡","structure_material":"煉瓦造2階建","registered":"2013.06.21(平成25.06.21)","register_no":"42 － 0105","desc":"佐世保港立神地区に建つ煉瓦造二階建、切妻造スレート葺。桁行三六メートル梁間九メートルの南棟の北壁を共有して同規模の北棟を増築。壁体は煉瓦二枚半積で腰と軒に蛇腹を廻らす。戸口と窓は鉄製両開扉付。小屋組はキングポストトラス。重厚な趣の倉庫建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009681"},{"id":"00009243","register_sub_id":"101","register_pk":"164796","name":"旧福幸製陶所絵書座","kana":"きゅうふっこうせいとうしょえかきざ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町井石郷字西ノ前2185-2他","lat":33.14080427,"lng":129.90766462,"geo_status":"db","era":"昭和元年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積213㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"東西棟で建ち、木造平屋建、桁行23メートル梁間7.7メートル、切妻造桟瓦葺で、南面に事務所を張出す。小屋をトラス組とする内部を、成形した陶磁器の乾燥と、絵付けを行う作業場として使用した。波佐見焼を代表する製陶工場を構成する工場建築のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009243"},{"id":"00009242","register_sub_id":"101","register_pk":"164795","name":"旧福幸製陶所細工場","kana":"きゅうふっこうせいとうしょさいくば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町井石郷字西ノ前2185-2他","lat":33.14101842,"lng":129.90781333,"geo_status":"db","era":"昭和元年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積309㎡","structure_material":"木造平屋建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"東西棟で建ち、木造平屋建、桁行32.6メートル梁間7.7メートル、切妻造桟瓦葺で、南面に下屋を通す。小屋をトラス組とし、開放的な内部を粘土置場や陶磁器の成形などの作業場に用いた。昭和初期における製陶工場の様相を今に留める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009242"},{"id":"00009241","register_sub_id":"101","register_pk":"164794","name":"旧福幸製陶所事務所","kana":"きゅうふっこうせいとうしょじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"長崎県","address":"長崎県東彼杵郡波佐見町井石郷字西ノ前2185-2他","lat":33.14114917,"lng":129.90756944,"geo_status":"db","era":"昭和元年頃","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積124㎡","structure_material":"木造平屋一部2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"通りに面し、木造平屋1部2階建、建築面積124平方メートル、切妻造桟瓦葺で、北側にもと事務所玄関であった切妻の張出しを設け、南面を下屋につくる。外壁は下見板張でペンキ塗とし、ガラス窓を連続させる。昭和初期の事務所建築で、街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009241"},{"id":"00009680","register_sub_id":"101","register_pk":"194676","name":"佐世保重工業二五〇トン起重機","kana":"させぼじゅうこうぎょうにひゃくごじゅっとんきじゅうき","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"長崎県","address":"長崎県佐世保市立神町22","lat":33.16479389,"lng":129.70754824,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"鉄骨造、高さ62m","structure_material":"鉄骨造","registered":"2013.06.21(平成25.06.21)","register_no":"42 － 0104","desc":"佐世保港の係船池に建つ鉄骨造ハンマーヘッド型起重機。全高六二メートル、主塔高四一メートル、腕長八一メートルを測る。英国サー・ウィリアム・アロル社製造、電動機はウェスティングハウス社製。当時国内最大の揚重能力を誇り、近代佐世保の港湾景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009680"},{"id":"00010076","register_sub_id":"101","register_pk":"196223","name":"マルイチ葬祭斎場（旧小林家住宅酒蔵）","kana":"まるいちそうさいさいじょう（きゅうこばやしけじゅうたくさかぐら）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県島原市弁天町1-7118-6","lat":32.78432927,"lng":130.37261987,"geo_status":"db","era":"明治末期／昭和前期移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造3階建、瓦葺、建築面積580㎡","structure_material":"土蔵造3階建","registered":"2014.04.25(平成26.04.25)","register_no":"42 － 0108","desc":"南北棟の切妻造で、桁行一四間梁間六間、土蔵造三階建の主体部の東面に、一階と二階で二段階に下屋を設け、三段屋根の外観を呈する。棟高約一四メートルに及ぶ大規模な土蔵建築で、国道に面して雄大な外観を見せており、島原の街路景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010076"},{"id":"00003334","register_sub_id":"101","register_pk":"104324","name":"三菱重工業長崎造船所ハンマーヘッド型起重機","kana":"みつびしじゅうこうぎょうながさきぞうせんしょはんまーへっどがたきじゅうき","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県長崎市飽の浦町1-1","lat":32.74203651,"lng":129.85890705,"geo_status":"db","era":"明治42／昭和36移設","year":1909,"year_source":"db","year_min":1909,"year_max":1909,"year_label":null,"structure":"鉄骨造、高さ62m","structure_material":"鉄骨造","registered":"2003.03.18(平成15.03.18)","register_no":"42 － 0020","desc":"長崎港に面する岸壁上に位置する。吊上能力１５０トン，高約６１ｍ，ジブ長約７３ｍ，英国マザーウェル・ブリッジ社製の大規模な起重機で，主柱間約１２ｍ四方とし，全体をトラスで組み上げる。造船技術の近代化を支え，近代長崎の港湾景観を代表する構造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003334"},{"id":"00003487","register_sub_id":"101","register_pk":"104477","name":"宮崎商店煙突","kana":"みやざきしょうてんえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"長崎県","address":"長崎県島原市上の町897","lat":32.79037255,"lng":130.36859979,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"煉瓦造、高さ12m","structure_material":"煉瓦造","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0028","desc":"店舗背面の旧釜場の北方，焼酎蔵の北寄り東側に隣接する旧麹室の南方に建つ。円形平面の煉瓦造煙突で，高さ約１２ｍ規模。頂部にリング状の持出しを２筋付けてトスカナ式円柱を思わせる。造り酒屋に付き物の工作物であるが，上の町のシンボル的存在でもある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003487"},{"id":"00003486","register_sub_id":"101","register_pk":"104476","name":"宮崎商店焼酎蔵","kana":"みやざきしょうてんしょうちゅうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"長崎県","address":"長崎県島原市上の町897","lat":32.79035131,"lng":130.36852524,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積197㎡","structure_material":"土蔵造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"42 － 0027","desc":"店舗の西方，敷地の南寄りに南北棟で建つ。桁行９間，梁間４間規模，切妻造，桟瓦葺，平入の２階建酒蔵で，棟梁は店舗と同じ「荒木輝美雄」であることが棟札から判明する。緩やかな坂道の中途に南妻面を見せて建ち，城方から島原街道を望む際の目印となる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003486"},{"id":"00010901","register_sub_id":"101","register_pk":"201736","name":"菊の城本舗店舗兼主屋","kana":"きくのしろほんぽてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県菊池市隈府字町95-2他","lat":32.98292,"lng":130.806953,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積305㎡","structure_material":"木造平屋一部2階建","registered":"2015.11.17(平成27.11.17)","register_no":"43 ‐ 0149","desc":"市街地の街路屈曲部に南面する造酒屋で、下階は広いミセと居間など、上階は上質な座敷飾をもつ接客空間を配する。建ちの高い二階建、入母屋造で正面に庇を通して出格子を設け、東端の平屋建はデンティルを飾り、洋風外観とする。街路景観の核となる酒造施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010901"},{"id":"00016457","register_sub_id":"101","register_pk":"536524","name":"旧隈府冷蔵製氷工場","kana":"きゅうわいふれいぞうせいひょうこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県菊池市隈府字南田775-1他","lat":32.98044444,"lng":130.80956111,"geo_status":"db","era":"昭和5年頃／昭和前期・同29年増築、令和2年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積439㎡","structure_material":"煉瓦造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0215","desc":"隈府の中心部に位置する旧製氷工場。敷地の中央部に建つ、煉瓦造平屋建切妻造桟瓦葺東西棟で、東端部の北と南に鉱滓煉瓦造平屋建桟瓦葺の倉庫を増築し、全体Ｔ字形平面とする。通りに面する北東部は半切妻造屋根とし壁面に記す工場名が操業時の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016457"},{"id":"00016458","register_sub_id":"101","register_pk":"536525","name":"旧隈府冷蔵倉庫（旧飲料水工場）","kana":"きゅうわいふれいぞうそうこ（きゅういんりょうすいこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"熊本県","address":"熊本県菊池市隈府字南田775-10","lat":32.98034722,"lng":130.80970278,"geo_status":"db","era":"昭和中期／令和2年改修","year":1957,"year_source":"estimated","year_min":1946,"year_max":1965,"year_label":"昭和中期","structure":"煉瓦造平屋建、瓦葺、建築面積73㎡","structure_material":"煉瓦造平屋建","registered":"2025.11.17(令和7.11.17)","register_no":"43 - 0216","desc":"製氷工場の南に位置する旧飲料水工場。鉱滓煉瓦造平屋建切妻造桟瓦葺の東西棟で、西に戸口を設ける。内部は一室の土間で鋼板天井張、小屋組はキングポスト・トラス。かつて冷凍冷蔵庫や冷凍タンクを配し、製氷工場と一体で地域の繁栄を伝える旧飲料水工場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016458"},{"id":"00004302","register_sub_id":"101","register_pk":"105292","name":"熊本学園大学産業資料館（旧熊本紡績電気室）","kana":"くまもとがくえんだいがくさんぎょうしりょうかん（きゅうくまもとぼうせきでんきしつ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市大江2-1903-2","lat":32.80363644,"lng":130.72665566,"geo_status":"db","era":"明治27／平成15移築","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"鉄筋コンクリート造及び煉瓦造平屋建、瓦葺、建築面積118㎡","structure_material":"鉄筋コンクリート造及び煉瓦造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"43 － 0072","desc":"ＪＲ熊本駅近くにあった紡績工場施設。イギリス積の煉瓦造，平屋建で，木造キングポストトラスの小屋組として，切妻造屋根を架ける。移築時に鉄筋コンクリート造で補強，当初壁は平側・妻側各１面となったが，隅の柱型や軒蛇腹の造形に見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004302"},{"id":"00014125","register_sub_id":"101","register_pk":"508385","name":"通潤酒造店舗及び主屋","kana":"つうじゅんしゅぞうてんぽおよびおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県上益城郡山都町浜町字新町54-1他","lat":32.68491111,"lng":130.98744167,"geo_status":"db","era":"明治前期／昭和10年代・同30年代後半・平成30年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積327㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"43 - 0185","desc":"日向往還浜町宿に位置し通りに面する町家。寄棟造の店舗背後に棟を直交させて主屋を接続し正面に妻を見せる。下屋中央を切上げ戸口とし、二階は虫籠窓を開ける。内部は中央に通路を通し、東は店舗等、西は事務所奥に主屋居室を設ける。宿場最大規模の町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014125"},{"id":"00014986","register_sub_id":"101","register_pk":"519246","name":"長谷川家住宅主屋","kana":"はせがわけじゅうたくおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県宇城市小川町小川字下苅萱112","lat":32.585575,"lng":130.70483056,"geo_status":"db","era":"明治16年／大正8年・昭和2年頃増築、同50年頃改修","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造2階建、瓦葺、建築面積183㎡","structure_material":"木造2階建","registered":"2024.03.06(令和6.03.06)","register_no":"43 - 0202","desc":"砂川右岸に位置し製糸業を営んだ商家の主屋。２階建切妻造平入桟瓦葺で通りに北面し、北西に角屋を延ばす。一階は東を土間、西に四室を並べ、二階にも四室を配す。かつては一階西下手の板間を荷造所、二階を女子寮として使用し、地域の製糸業の歴史を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014986"},{"id":"00006459","register_sub_id":"101","register_pk":"107442","name":"浜田醤油旧圧搾機室","kana":"はまだしょうゆきゅうあっさくきしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"大正","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.77723376,"lng":130.63573342,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"土蔵造平屋建、瓦葺、建築面積69㎡","structure_material":"土蔵造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0097","desc":"敷地北辺、三番蔵と旧原料倉庫の間に建つ。桁行６間、梁間３間、土蔵造平屋建、桟瓦葺。腰は下見板張とし、屋根の棟通りには採光窓を設ける。長大な土蔵の壁が連続する景観の中間で、通りに妻壁を見せて建ち、街路景観のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006459"},{"id":"00006461","register_sub_id":"101","register_pk":"107444","name":"浜田醤油旧石室","kana":"はまだしょうゆきゅういしむろ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.77709121,"lng":130.63563997,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"石造平屋建、建築面積63㎡","structure_material":"石造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0099","desc":"敷地南辺の中央付近に建ち、建築面積６３㎡、石造、平屋建である。石を積み上げ、外部をモルタル塗とし、内部を２室に間仕切る。現在は倉庫だが、もとは麹室で、温湿度を一定に保つため密閉性を高めている。醸造業創始時の醸造工程の一端を伝える遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006461"},{"id":"00006460","register_sub_id":"101","register_pk":"107443","name":"浜田醤油旧原料倉庫","kana":"はまだしょうゆきゅうげんりょうそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.777233,"lng":130.63562807,"geo_status":"db","era":"明治初期／大正期改造","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積120㎡","structure_material":"土蔵造2階建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0098","desc":"旧圧搾機室の西側に建つ、桁行５間半、梁間５間、土蔵造２階建。切妻造桟瓦葺。外観は白漆喰仕上げで、腰を下見板張とし、外壁の中段に水切り瓦をつける。酒屋の建物と機械室を接続、改造して穀物倉庫としたもので、業務拡張時の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006460"},{"id":"00006464","register_sub_id":"101","register_pk":"107447","name":"浜田醤油給水塔","kana":"はまだしょうゆきゅうすいとう","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"low","period":"昭和中","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.77711886,"lng":130.63539814,"geo_status":"db","era":"昭和25頃","year":1950,"year_source":"db","year_min":1950,"year_max":1950,"year_label":null,"structure":"煉瓦造、高さ7m、門柱2基付","structure_material":"煉瓦造","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0100","desc":"敷地南面西寄りに建つ、幅２ｍ、奥行２ｍ、高さ７ｍの煉瓦造給水塔である。塔内部のポンプで地下水を汲み上げ、使用している。外壁の煉瓦は長手積で、接続する煉瓦塀と一体的に建設されている。煙突と併せて、旧白川沿いの景観を特徴づけている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006464"},{"id":"00006458","register_sub_id":"101","register_pk":"107441","name":"浜田醤油三番蔵","kana":"はまだしょうゆさんばんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県熊本市小島中町107","lat":32.777248,"lng":130.635925,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造平屋建、瓦葺、建築面積218㎡","structure_material":"土蔵造平屋建","registered":"2007.10.02(平成19.10.02)","register_no":"43 － 0096","desc":"敷地の東北角、店舗の北隣に建つ。桁行１２間、梁間４間、土蔵造平屋建、切妻造桟瓦葺。正面の海鼠壁を店舗と一連にして調和させるが、平入の店舗に対して、三番蔵は妻入で大きな妻壁を見せ、街路景観に変化を与える。醸造業創始時の面影を伝える大型の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006458"},{"id":"00014550","register_sub_id":"101","register_pk":"513964","name":"街蔵石倉（旧緑屋石倉）","kana":"まちくらいしくら（きゅうみどりやいしくら）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"熊本県","address":"熊本県人吉市紺屋町41-1","lat":32.21449722,"lng":130.76030278,"geo_status":"db","era":"明治35年頃／昭和16年頃移築","year":1902,"year_source":"db","year_min":1902,"year_max":1902,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積148㎡","structure_material":"石造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"43 - 0198","desc":"旧城下の市街地に所在する味噌醸造や原材料保管に用いた石倉。寄棟造妻入桟瓦葺で、西側を換気採光のため改修。壁は切石布積江戸切仕上、小屋組はキングポスト・トラスとする。近代に人吉地方の溶結凝灰岩を用い、数多く建築された石倉の遺構として貴重。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014550"},{"id":"00014551","register_sub_id":"101","register_pk":"513965","name":"街蔵麴室（旧緑屋麹室棟）","kana":"まちくらこうじむろ（きゅうみどりやこうじむろとう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"熊本県","address":"熊本県人吉市紺屋町41-1","lat":32.21448056,"lng":130.76012778,"geo_status":"db","era":"昭和16年頃／同41年改修","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造一部コンクリートブロック造平屋建、瓦葺、建築面積64㎡","structure_material":"木造一部コンクリートブロック造平屋建","registered":"2023.02.27(令和5.02.27)","register_no":"43 - 0199","desc":"旧城下の市街地に所在する味噌醸造元の麹室棟。切妻造桟瓦葺で南側軒を高く招き屋根として越屋根を備える。外壁は北半をコンクリートブロック布積、南半を開放とする。内部は元は北東側桁行４間、梁間２間を麹室とした。石倉と一体で味噌作りの景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014551"},{"id":"00004303","register_sub_id":"101","register_pk":"105293","name":"マミフラワーデザイン熊本教室花峰館（旧鐘淵紡績熊本工場診療所）","kana":"まみーふらわーでざいんくまもときょうしつかほうかん（きゅうかねがふちぼうせきくまもとこうじょうしんりょうじょ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"熊本県","address":"熊本県熊本市河内町岳字茶碗山1844-356、365","lat":32.810703,"lng":130.644196,"geo_status":"db","era":"明治44／平成15移築","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"43 － 0073","desc":"ＪＲ熊本駅近くにあった紡績工場の診療所施設。木造平屋建，寄棟造，桟瓦葺，平入で，正面中央に切妻造鉄板葺の玄関を突出する。煉瓦造の布基礎で，外壁は腰縦板張，中央下見板張，上部ハーフティンバー風に扱い，内外とも瀟洒な洋風意匠でよく纏まっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004303"},{"id":"00010539","register_sub_id":"101","register_pk":"199478","name":"荒木家住宅勝手蔵","kana":"あらきけじゅうたくかってぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県玖珠郡玖珠町大字森938","lat":33.300556,"lng":131.158778,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"44 － 0208","desc":"主屋の奥座敷後方に東西棟で建つ。桁行六・九メートル梁間四・九メートル、土蔵造二階建、切妻造桟瓦葺。外壁漆喰塗で鉢巻を廻らし、腰は陶板を用いた海鼠壁とする。東妻を戸口として掛子塗戸を開き、小屋は和小屋である。特異な色合いの腰壁が目を引く土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010539"},{"id":"00010538","register_sub_id":"101","register_pk":"199477","name":"荒木家住宅酒蔵","kana":"あらきけじゅうたくさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県玖珠郡玖珠町大字森938","lat":33.300766,"lng":131.158767,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積121㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"44 － 0207","desc":"主屋の北西方に南北棟で建ち、桁行一八メートル規模の土蔵造二階建で、切妻造桟瓦葺である。東面戸口に庇を付け、外壁漆喰塗で開口部廻りは丸みを帯びた縁取りとする。小屋は洋小屋を組む。正面階境の水切と二階窓の庇に瓦を並べて、表情をもたせた大型土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010538"},{"id":"00010537","register_sub_id":"101","register_pk":"199476","name":"荒木家住宅主屋","kana":"あらきけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県玖珠郡玖珠町大字森938他","lat":33.30057,"lng":131.158935,"geo_status":"db","era":"大正11／昭和50代・平成19改修","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木造2階建、瓦葺、建築面積235㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"44 － 0206","desc":"森城下の街路に東面して建つ。上下階とも出桁造で二階は軒先まで塗込め、屋根北端に載せた唐破風造の小室に布袋像を置く。一階は北寄りを広い通り土間、南側前面をミセ、奥に四室を配し南奥を主座敷とする。材工共に上質で、旧城下町に彩りを添える近代建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010537"},{"id":"00003174","register_sub_id":"101","register_pk":"104164","name":"井上家住宅酒蔵","kana":"いのうえけじゅうたくさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県日田市鶴河内町4279","lat":33.376652,"lng":130.892563,"geo_status":"db","era":"弘化4","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積108㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"44 － 0085","desc":"門の東側にある２階建，切妻造，桟瓦葺の大規模な土蔵。外観は漆喰壁と腰に海鼠瓦を張る。入口は北側に２個所あり，東半は什器等を収める道具蔵の性格を持つ。内部は板張りで小屋は水平梁と登梁を１間毎に交互にかける構造。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003174"},{"id":"00011229","register_sub_id":"101","register_pk":"205336","name":"井上酒造煙突","kana":"いのうえしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和中","pref":"大分県","address":"大分県日田市大字大肥字堂迫2299-1","lat":33.361329,"lng":130.878866,"geo_status":"db","era":"昭和28頃","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"煉瓦造、高さ18m","structure_material":"煉瓦造","registered":"2016.08.01(平成28.08.01)","register_no":"44 - 0222","desc":"敷地西奥に位置する煉瓦造の煙突。基底部は一・四メートル角、高さは約一八メートルである。基部にはアーチ状開口部が設けられ、煉瓦をイギリス積としている。市内に三基残る大型煉瓦造煙突の一つで、酒造業らしい地域のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011229"},{"id":"00011227","register_sub_id":"101","register_pk":"205334","name":"井上酒造店舗兼主屋","kana":"いのうえしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県日田市大字大肥字堂迫2299-1","lat":33.361115,"lng":130.879059,"geo_status":"db","era":"大正3／昭和18改修","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積454㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"44 - 0220","desc":"井上準之助の生家として知られる造酒屋。店舗兼主屋は入母屋屋根の式台玄関を備えた大規模なもので、店に用いる広い土間と、整った座敷を並べる床上部からなる。当初茅葺平屋建であったが、戦前期に二階を増築して瓦葺とし、家業の隆盛に伴う発展を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011227"},{"id":"00011228","register_sub_id":"101","register_pk":"205335","name":"井上酒造木造蔵","kana":"いのうえしゅぞうもくぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県日田市大字大肥字寺田2219-1他","lat":33.361606,"lng":130.879149,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造2階建、瓦葺、建築面積373㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"44 - 0221","desc":"当初は仕込蔵として建設された。屋根は半切妻とし、外壁は漆喰壁として腰に竪板を張る。小屋組はクイーンポストトラスを架け、下弦材に約一六メートルの一丁材を用いて大スパンを飛ばす。地元大工らが大空間を実現するため、近代構法を取り入れたことを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011228"},{"id":"00001160","register_sub_id":"101","register_pk":"102150","name":"太田缶詰工場石倉","kana":"おおたかんづめこうじょういしぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県大分市大字白木336","lat":33.24293179,"lng":131.87462129,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"石造平屋建，瓦葺，建築面積106㎡","structure_material":"石造平屋建","registered":"1999.06.07(平成11.06.07)","register_no":"44 － 0043","desc":"主屋棟の北側に建つ外壁廻りを石造とした大型の倉で、軒廻りや妻壁は漆喰仕上げとし正面（南面）は左右の出入口のみの閉鎖的な外観になる。建築年代は、主屋などよりわずかに遅れたといわれる。開口部及び内装は工場として改修されたが、外観の保存はよい。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001160"},{"id":"00001158","register_sub_id":"101","register_pk":"102148","name":"太田缶詰工場主屋","kana":"おおたかんづめこうじょうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県大分市大字白木332","lat":33.24265928,"lng":131.87413976,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造２階建，瓦葺，建築面積401㎡","structure_material":"木造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"44 － 0041","desc":"工場の中心をなす建物で、木造２階建、寄棟造の主体部及び北寄り背後に接続する角屋からなる。主体部の１階平面は、南半部を接客用の座敷や和室が連なる居住部分とし、北半部に工場事務室を併設する。玄関部分を洋風につくるなど、特徴的な意匠で知られる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001158"},{"id":"00001159","register_sub_id":"101","register_pk":"102149","name":"太田缶詰工場土蔵","kana":"おおたかんづめこうじょうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県大分市大字白木336","lat":33.24293179,"lng":131.87462129,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造２階建，瓦葺，建築面積41㎡","structure_material":"土蔵造２階建","registered":"1999.06.07(平成11.06.07)","register_no":"44 － 0042","desc":"水産物加工と雑貨販売を家業とした初代が、明治２３年に缶詰の本格的な生産をはじめ、明治４１年には現在地に新工場を建て操業を開始した。土蔵は、切妻造、２階建で、外壁を漆喰仕上げとし、腰下を板貼りとする標準的な造りになり、全体的に保存も良い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001159"},{"id":"00007332","register_sub_id":"101","register_pk":"108314","name":"可兒醤油店舗兼主屋","kana":"かにしょうゆてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県臼杵市大字臼杵字本町218-1他","lat":33.11934034,"lng":131.79850628,"geo_status":"db","era":"明治10／大正後期改修","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造2階建、瓦葺、建築面積193㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0147","desc":"通りに北面する平入町家。正面６間半奥行５間半規模、切妻造桟瓦葺で、正・背面に下屋庇を設け、背面には片流屋根を直角に付設。漆喰仕上げの大壁で、２階には虫籠窓４ヶ所を開ける。１階を土間床のミセ、２階を居室とする。臼杵における大規模な商家の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007332"},{"id":"00007333","register_sub_id":"101","register_pk":"108315","name":"可兒醤油西店舗","kana":"かにしょうゆにしてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県臼杵市大字臼杵字本町218-1他","lat":33.119492,"lng":131.79837,"geo_status":"db","era":"江戸末期／大正後期改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積78㎡","structure_material":"木造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"44 － 0148","desc":"店舗兼主屋の西に隣接して建つ。正面３間半奥行６間、切妻造桟瓦葺で、正・背面に下屋庇を付ける。大壁造の漆喰仕上げで、２階に虫籠窓３ヶ所を開ける。店舗兼主屋と同じ正面構えで伝統的な街路景観を形成するが、棟高や軒まわり、窓の大きさに違いを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007333"},{"id":"00000503","register_sub_id":"101","register_pk":"101493","name":"萱島酒造井戸屋形","kana":"かやしましゅぞういどやかた","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52527637,"lng":131.72556579,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建，瓦葺，建築面積12㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0029","desc":"仕込み蔵の西側に位置する立ちの割には間口がやや広めの井戸屋形で，切妻の屋根をかける。中央に醸造に必要な清水を汲む切石組の井戸がある。小規模な建屋であるが，開放とする南面妻側の入り口には注連縄を張って，日頃から丁寧に管理されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000503"},{"id":"00000504","register_sub_id":"101","register_pk":"101494","name":"萱島酒造裏門","kana":"かやしましゅぞううらもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52517446,"lng":131.72562447,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造及び木造，瓦葺","structure_material":"煉瓦造及び木造","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0030","desc":"醸造所の裏手にある門で，煉瓦造の親柱一対が保存される。鉄製の門扉は後補のもの。仕込み蔵の南側に付設する下屋に接するように建ち，切妻の瓦屋根が付くほかシャッターも付設されている等改造があるが，醸造所の歴史を知る上で意味ある門である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000504"},{"id":"00000499","register_sub_id":"101","register_pk":"101489","name":"萱島酒造煙突","kana":"かやしましゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.5250324,"lng":131.7258005,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"煉瓦造，高さ17m","structure_material":"煉瓦造","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0025","desc":"ムロマエの北側に隣接する平面八角形の煉瓦蔵煙突で，高さ２０ｍある。排煙口の意匠や煙道に付加された帯金具がアクセントとなっている。遠方からも望見され，古くから醸造所を象徴する工作物として付近の目印となっており広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000499"},{"id":"00000495","register_sub_id":"101","register_pk":"101485","name":"萱島酒造北蔵","kana":"かやしましゅぞうきたぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52535357,"lng":131.72599814,"geo_status":"db","era":"明治39","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積220㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0021","desc":"仕込み蔵の東側にあり，棟を直行して建つ木造平屋建の建物。他の建物と異なり，内部に棹縁天井をはった丁寧奈造りになる。間口４間半に対して奥行き１３間と長い。近年，東妻に別棟が附属したが，本体部は保存がよい。製品置場（瓶詰め）として知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000495"},{"id":"00000500","register_sub_id":"101","register_pk":"101490","name":"萱島酒造旧麹室","kana":"かやしましゅぞうきゅうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52492122,"lng":131.72573873,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積40㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0026","desc":"旧ムロマエの南に建つ建物で，間口４間，梁間３間の木造平屋建になる。中蔵とは棟を平行にし，外壁は周囲を板貼とする。南妻側の上部に気抜きの小窓が付き，意匠上のアクセントとなる。現在は，吟醸酒を長期保存するための施設として使われている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000500"},{"id":"00000498","register_sub_id":"101","register_pk":"101488","name":"萱島酒造旧ムロマエ","kana":"かやしましゅぞうきゅうむろまえ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.5249799,"lng":131.72580358,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積79㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0024","desc":"敷地の南側に位置する木造平屋建の麹を冷やすための蔵造の建物。桁行５間，梁間４間半の規模になり，中蔵とは棟を直交して建つ。小屋組は和小屋とし，外壁は漆喰仕上げとする。醸造所で最も古い建物で，歴史を知る上で貴重である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000498"},{"id":"00000496","register_sub_id":"101","register_pk":"101486","name":"萱島酒造米蔵","kana":"かやしましゅぞうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52511887,"lng":131.72610314,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建，瓦葺，建築面積171㎡","structure_material":"土蔵造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0022","desc":"土蔵造２階建の蔵で，漆喰仕上げの簡素な造りになる。外壁は２階窓まで延びる縦板を貼る。窓は，外側に簡素な枠をつけたもので板戸片引きとする。県道に面して建ち，煉瓦蔵の煙突とともに萱島酒造を象徴する建物として親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000496"},{"id":"00000494","register_sub_id":"101","register_pk":"101484","name":"萱島酒造仕込み蔵","kana":"かやしましゅぞうしこみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52538446,"lng":131.72574182,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建，瓦葺，建築面積1123㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0020","desc":"萱島酒造は明治６年の創業で親子４代にわたる醸造所である。仕込み蔵は，木造２階建，寄棟造，瓦葺の大規模な倉庫建築で，内部は１，２階とも板床で，小屋はトラス組とする。敷地の奥手に建つが，風格ある大屋根は外部からも望見でき，広く親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000494"},{"id":"00000501","register_sub_id":"101","register_pk":"101491","name":"萱島酒造中蔵（搾り場）","kana":"かやしましゅぞうなかぐら（しぼりば）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52509416,"lng":131.72572638,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階建，瓦葺，建築面積687㎡","structure_material":"木造2階建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0027","desc":"間口４間，奥行２６間の長大な木造２階建，寄棟造の建物で，棟を南北に向ける。小屋組は，単純なキングポストトラスで，左右の束は挟み束とする。醸造所の建築群のなかで，仕込み蔵とともに外壁を板貼りとする壮大な外観は，ひときわ目立つ存在である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000501"},{"id":"00000505","register_sub_id":"101","register_pk":"132558","name":"萱島酒造木塀","kana":"かやしましゅぞうもくべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.52477916,"lng":131.72583447,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"屋根塀，鉄板葺，延長65m","structure_material":"屋根塀","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0031","desc":"敷地の南側を限る塀で，腰下を煉瓦積としその上に木造の屋根塀を載せた構造になる。木造屋根塀の部分は，一間毎に柱を立て貫を渡し，その上下２段に間渡しを渡す簡素なもので，屋根は鉄板葺とする。明治以来の醸造所の繁栄の様子を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000505"},{"id":"00000497","register_sub_id":"101","register_pk":"101487","name":"萱島酒造門口倉庫","kana":"かやしましゅぞうもんぐちそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.5250324,"lng":131.72610006,"geo_status":"db","era":"大正5","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造平屋建，瓦葺，建築面積50㎡","structure_material":"木造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0023","desc":"米蔵に接続して建つ平屋建の倉庫兼門屋とする建物。米蔵側の一間半が間口で、門扉はシャッターに代わる。倉庫部分は，間口３間，梁間２間と小規模で，真壁造に腰板を貼る簡素な造りとなる。居宅と一体の醸造所を構成する付属的な施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000497"},{"id":"00000502","register_sub_id":"101","register_pk":"101492","name":"萱島酒造冷蔵蔵（旧醸造所）","kana":"かやしましゅぞうれいぞうぐら（きゅうじょうぞうしょ）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"大分県","address":"大分県国東市国東町綱井392-1","lat":33.5250849,"lng":131.72561211,"geo_status":"db","era":"明治27","year":1894,"year_source":"db","year_min":1894,"year_max":1894,"year_label":null,"structure":"土蔵造平屋建，瓦葺，建築面積198㎡","structure_material":"土蔵造平屋建","registered":"1998.01.16(平成10.01.16)","register_no":"44 － 0028","desc":"西蔵の西側に建つ。間口５間半，奥行１１間の平屋建の建物。醸造所の中で最も古い建物として知られ，昭和４年から冷蔵庫として使用している。内部は，籾殻を詰めた二重の板壁に改修し保温性を高めている。醸造工程を知る上で意義深い建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000502"},{"id":"00000278","register_sub_id":"101","register_pk":"101268","name":"小手川酒造蔵","kana":"こてがわしゅぞうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"大分県","address":"大分県臼杵市大字臼杵字浜町538","lat":33.12068836,"lng":131.79702087,"geo_status":"db","era":"慶応元","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階建，瓦葺，建築面積368㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"44 － 0008","desc":"主屋の北に並んで建つ蔵。道に面して妻を見せる奥行の長い大規模な蔵で，醸造場として用いられている。正面妻の２階窓の上部に水切り瓦を付け，腰を海鼠壁で飾る等の，伝統的な技法による装飾に見るべきものがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000278"},{"id":"00000277","register_sub_id":"101","register_pk":"101267","name":"小手川酒造主屋","kana":"こてがわしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"大分県","address":"大分県臼杵市大字臼杵字浜町538","lat":33.12054988,"lng":131.79702087,"geo_status":"db","era":"慶応元","year":1865,"year_source":"db","year_min":1865,"year_max":1865,"year_label":null,"structure":"木造2階建，瓦葺，建築面積256㎡","structure_material":"木造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"44 － 0007","desc":"広い間口をもつ大規模な二階建て平入の町家で，二階の外壁を白漆喰の大壁造とする。醸造業が盛んで漆喰塗り大壁の町家が多く残る臼杵の町並のなかで，とくに規模が大きく建設年代が古い建築のひとつとしてよく知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000277"},{"id":"00002467","register_sub_id":"101","register_pk":"103457","name":"英国館","kana":"えいこくかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮崎県","address":"宮崎県西臼杵郡日之影町大字見立2107-8","lat":32.78772684,"lng":131.45497232,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造平屋建、鉄板葺、建築面積350㎡","structure_material":"木造平屋建","registered":"2001.10.12(平成13.10.12)","register_no":"45 － 0010","desc":"神戸の貿易商ハンター（範多範三郎）により経営された見立鉱山の外国人技師クラブ兼ハンター別荘として建設。木造平屋建，下見板張，鉄板葺切妻屋根で，横長の連続窓を配したモダニズム建築になり，地元では「レーモンド様式」の建築として名がとおっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002467"},{"id":"00012670","register_sub_id":"101","register_pk":"367964","name":"古澤醸造一号蔵","kana":"ふるさわじょうぞういちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4748","lat":31.553848,"lng":131.379852,"geo_status":"geocoded","era":"明治25年頃／平成15年改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積132㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"45 － 0101","desc":"敷地東南隅に建つ。土蔵造二階建、南北棟の切妻造で、西北二面に戸口を開く。柱を一間毎に立て、筋交を襷状に入れて固める。二階床組は大径梁を用い、小屋組はキングポストトラスである。焼酎の仕込を行う長大な土蔵で、敷地内醸造施設の中核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012670"},{"id":"00012672","register_sub_id":"101","register_pk":"367966","name":"古澤醸造表門及び塀","kana":"ふるさわじょうぞうおもてもんおよびへい","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4748","lat":31.553848,"lng":131.379852,"geo_status":"geocoded","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"表門 木造、瓦葺、間口1.8m 塀 木造、瓦葺、総延長18m","structure_material":"表門 木造","registered":"2018.11.02(平成30.11.02)","register_no":"45 － 0103","desc":"店舗兼主屋の正面南側に接続し、座敷棟の前庭と街路を区切る門塀。表門は街路から後退し、西面して建つ切妻造桟瓦葺の腕木門。塀は真壁造、漆喰塗の腰縦板張で、表門北側に額縁付の格子窓、南側に変形格子窓を並べる。街路沿いの歴史的景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012672"},{"id":"00012668","register_sub_id":"101","register_pk":"367962","name":"古澤醸造麹室・検定室及び作業場","kana":"ふるさわじょうぞうこうじむろ・けんていしつおよびさぎょうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4748","lat":31.553848,"lng":131.379852,"geo_status":"geocoded","era":"明治25年頃／昭和30年頃増築、昭和36年改修","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"土蔵造及び木造平屋建、瓦葺、建築面積116㎡","structure_material":"土蔵造及び木造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"45 － 0099","desc":"敷地中央に南北棟で建つ。土蔵造の麹室・作業場と木造の検定室からなり、切妻屋根をかける。麹室は内壁と天井を板張として、板裏に籾殻を詰め、西面二箇所、東面一箇所に採光の硝子窓、天井に換気口一箇所を設ける。伝統的な醸造業に欠かせない施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012668"},{"id":"00012667","register_sub_id":"101","register_pk":"367961","name":"古澤醸造店舗兼主屋","kana":"ふるさわじょうぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4748","lat":31.553848,"lng":131.379852,"geo_status":"geocoded","era":"大正2年頃／大正12年頃増築、平成15年改修","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積245㎡","structure_material":"木造2階一部平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"45 － 0098","desc":"大堂津中心部の街路に西面して建つ。寄棟造二階建の一階正面は黒漆喰塗大壁で、戸袋も塗込めた重厚なつくりとする。南側は入母屋造平屋建の座敷棟で正面北端に玄関を構え、創意ある意匠の座敷や便所、浴室を配する。醸造業で栄えた町の様相を伝える大型町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012667"},{"id":"00012671","register_sub_id":"101","register_pk":"367965","name":"古澤醸造二号蔵","kana":"ふるさわじょうぞうにごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4748","lat":33.29920833,"lng":130.22647778,"geo_status":"db","era":"明治後期／昭和50年代・平成15年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"45 － 0102","desc":"一号蔵の北側、敷地北面に建つ。土蔵造二階建、東西棟の切妻造で、南面に戸口を開く。太い柱を半間毎に立てて貫で固め、大径梁で二階床組をつくる。小屋組はキングポストトラスである。一号蔵と同様の焼酎の仕込蔵で、敷地内醸造施設の中核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012671"},{"id":"00012669","register_sub_id":"101","register_pk":"367963","name":"古澤醸造瓶詰操作場","kana":"ふるさわじょうぞうびんづめそうさじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4748","lat":31.553848,"lng":131.379852,"geo_status":"geocoded","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積31㎡","structure_material":"土蔵造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"45 － 0100","desc":"店舗兼主屋背面に南面して建つ。土蔵造平屋建、切妻造桟瓦葺で、柱を半間毎に立て、小屋組を和小屋とする。外壁は漆喰塗の腰モルタル塗で、戸口上部のペディメントなど意匠を凝らす。醸造業の近代化を示す建物で、敷地内醸造施設のアクセントとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012669"},{"id":"00013905","register_sub_id":"101","register_pk":"507863","name":"宮田本店石蔵","kana":"みやたほんてんいしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"宮崎県","address":"宮崎県日南市大堂津四丁目4737-1他","lat":31.55575,"lng":131.37972222,"geo_status":"db","era":"昭和3年","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積261㎡、袖塀及び門柱付","structure_material":"石造平屋建","registered":"2021.06.24(令和3.06.24)","register_no":"45 － 0111","desc":"日向灘に近い大堂津の通り沿いに建つ醤油蔵。切石積に寄棟造桟瓦葺の屋根を載せ、前方に切石積の袖塀と門柱を設ける。正面に欠円アーチの出入口を二連並べ、内部は一室で石造の仕込用タンクを据える。小屋はトラス。醸造の盛んな大堂津の歴史的風致を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013905"},{"id":"00006956","register_sub_id":"101","register_pk":"107938","name":"九州電力大田発電所本館","kana":"きゅうしゅうでんりょくおおたはつでんしょほんかん","category":"産業2次","subcategory":"建築物","type_guess":"発電・機械","type_guess_confidence":"high","period":"明治","pref":"鹿児島県","address":"鹿児島県日置市伊集院町大田字管田3109-1","lat":31.63293776,"lng":130.36798864,"geo_status":"db","era":"明治41／昭和28改修","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積188㎡、塔屋付","structure_material":"石造平屋建","registered":"2008.03.07(平成20.03.07)","register_no":"46 － 0061","desc":"神之川の中流左岸に位置する水力発電所施設。桁行１５ｍ梁間１２ｍ規模の石造平屋建で、南隅部に八角形塔屋を張り出し、妻面には島津家の家紋をあしらう特徴的な外観。鹿児島の近代化に貢献した島津家の経営に係る鉱山に関連する施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006956"},{"id":"00002346","register_sub_id":"101","register_pk":"103336","name":"白金酒造石蔵","kana":"しらかねしゅぞういしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"鹿児島県","address":"鹿児島県姶良市脇元1943-1","lat":31.70117808,"lng":130.61433241,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"石造、瓦葺、建築面積222㎡","structure_material":"石造","registered":"2001.08.28(平成13.08.28)","register_no":"46 － 0010","desc":"明治２年創業の造り酒屋の仕込蔵。ＪＲ日豊本線重富駅の南方，国道１０号線に西面して建つ。切妻造，桟瓦葺，もと平入の木骨石造蔵で，県内に数多く残る凝灰岩系石蔵のひとつであるが，石目地を極力薄くして精巧に積みあげている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002346"},{"id":"00006561","register_sub_id":"101","register_pk":"107544","name":"丁子屋石蔵","kana":"ちょうじやいしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"鹿児島県","address":"鹿児島県南さつま市加世田唐仁原6026","lat":31.42684222,"lng":130.29519051,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"石造平屋建、瓦葺、建築面積65㎡","structure_material":"石造平屋建","registered":"2007.07.31(平成19.07.31)","register_no":"46 － 0040","desc":"道路に面して建つ。桁行１０ｍ，梁間６ｍの規模で，石造平屋建，切妻造，瓦葺，妻入とする。内部を１室とし，小屋組は陸梁の中央に束を立て，梁端部近くから登梁を架け，凝灰岩の切石は成，厚み共に１尺で，堅牢な外観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006561"},{"id":"00005212","register_sub_id":"101","register_pk":"106202","name":"旧東洋製糖北大東出張所","kana":"きゅうとうようせいとうきただいとうしゅっちょうじょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港29-1","lat":25.95424454,"lng":131.28637095,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"石造一部鉄筋コンクリート造平屋建、建築面積712㎡","structure_material":"石造一部鉄筋コンクリート造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"47 － 0008","desc":"海を望む島西北部の高台に建つ。建物の角をコンクリートで固め，壁面を石灰岩の布積で築いた凹形平面の建築物で，玄関ポーチにはＲＣ造の列柱を配する。事務所と売店を収容した燐鉱事業の拠点となった施設で，北大東島の近代産業繁栄の歴史を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005212"},{"id":"00005800","register_sub_id":"101","register_pk":"106788","name":"旧東洋製糖燐鉱石貯蔵庫","kana":"きゅうとうようせいとうりんこうせきちょぞうこ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港81-11","lat":25.954002,"lng":131.28511,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造及び鉄筋コンクリート造、面積2358㎡","structure_material":"石造及び鉄筋コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"47 － 0022","desc":"島西北部の高台に位置する。島内で採掘した燐鉱石を，集約的に貯蔵するために築かれた施設。延長約４０ｍの石造壁体に，４本の軌道用鉄筋コンクリート造トンネルが貫通するつくり。石灰岩を，乱積により巧みに積み上げた大規模な石造壁体が特徴的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005800"},{"id":"00005801","register_sub_id":"101","register_pk":"106789","name":"旧東洋製糖燐鉱石積荷桟橋","kana":"きゅうとうようせいとうりんこうせきつみにさんばし","category":"産業2次","subcategory":"土木構造物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"沖縄県","address":"沖縄県島尻郡北大東村字港地先","lat":25.953951,"lng":131.284134,"geo_status":"db","era":"大正8頃","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"鉄筋コンクリート造、延長18m","structure_material":"鉄筋コンクリート造","registered":"2006.10.18(平成18.10.18)","register_no":"47 － 0023","desc":"燐鉱石貯蔵庫より約５０ｍ西方に位置する。石灰岩よりなる岸壁から突き出た延長１８ｍの鉄筋コンクリート造構造物で，天端に２列の溝を設けて，２本の軌道を引き込むつくりとする。燐鉱採掘関連施設のひとつで，北大東島の近代産業繁栄の歴史を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005801"},{"id":"00009694","register_sub_id":"101","register_pk":"194690","name":"旧西中共同製糖場煙突","kana":"きゅうにしなかきょうどうせいとうじょうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"沖縄県","address":"沖縄県宮古島市城辺字西里添西底原621-6","lat":24.75545111,"lng":125.36269701,"geo_status":"db","era":"昭和17","year":1942,"year_source":"db","year_min":1942,"year_max":1942,"year_label":null,"structure":"煉瓦造、高さ13m","structure_material":"煉瓦造","registered":"2013.06.21(平成25.06.21)","register_no":"47 － 0081","desc":"サトウキビ畑の中に建つ煉瓦煙突。基部の平面は二・七メートル角で、高さは一三メートル、煉瓦造、イギリス積で、東西面の基部に欠円アーチの煙道を残す。宮古島の伝統産業である製糖業を象徴する煙突で、県内でも希少な昭和前期の製糖工場の遺構である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009694"},{"id":"00002492","register_sub_id":"101","register_pk":"103482","name":"上川倉庫一号倉庫","kana":"かみかわそうこいちごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.76282255,"lng":142.36384052,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木骨煉瓦造平屋建、鉄板葺、建築面積165㎡","structure_material":"木骨煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0039","desc":"ＪＲ旭川駅前の約０．５ｈａの敷地を占める上川倉庫群は，グリッド状街路網の１区画分を囲むように配置されている。平側で通りに面し，敷地正面の事務所西側に位置する木骨煉瓦造平屋建の一号倉庫は，現在多目的ホールとして市民に広く活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002492"},{"id":"00002494","register_sub_id":"101","register_pk":"103484","name":"上川倉庫三号倉庫（チェアーズギャラリー）","kana":"かみかわそうこさんごうそうこ（ちぇあーずぎゃらりー）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.762608,"lng":142.36349904,"geo_status":"db","era":"明治36","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木骨煉瓦造平屋建、鉄板葺、建築面積223㎡","structure_material":"木骨煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0041","desc":"当初，上川倉庫は穀物貯蔵に用いられた。三号倉庫は敷地西角を占め，二号倉庫と横並びで配置される。小屋組を木製キングポストトラスとし，焼過ぎ煉瓦を用いた基壇と小口を二枚重ねた歯飾り付の蛇腹が外観を引き締める。現在，椅子の展示室として活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002494"},{"id":"00002491","register_sub_id":"101","register_pk":"103481","name":"上川倉庫事務所","kana":"かみかわそうこじむしょ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.76274907,"lng":142.3640528,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積120㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0038","desc":"上川倉庫群の正面，宮下通側のほぼ中央に立つ敷地内唯一の木造建築。東面に煉瓦の煙突を建ちあげた下見板張洋館で，妻面をペディメント状に造りファイニアルを載せ，２階中央に要石及び額縁飾付半円アーチ窓を配するなど正面妻側に特に丹念な意匠を施す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002491"},{"id":"00002497","register_sub_id":"101","register_pk":"103487","name":"上川倉庫十一号倉庫（大雪地ビール館）","kana":"かみかわそうこじゅういちごうそうこ（だいせつじびーるかん）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.76261121,"lng":142.36389431,"geo_status":"db","era":"大正2","year":1913,"year_source":"db","year_min":1913,"year_max":1913,"year_label":null,"structure":"木骨煉瓦造平屋建、鉄板葺、建築面積430㎡","structure_material":"木骨煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0044","desc":"敷地の中央にある。倉庫群の中で最も規模が大きく，最後に建設された倉庫。妻側が隠れる他の倉庫と異なり，欠円アーチの開口部のみでなく，２段の歯飾付蛇腹を有す三角ペディメントを両妻側に設ける。現在，ビアホールとして活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002497"},{"id":"00002496","register_sub_id":"101","register_pk":"103486","name":"上川倉庫十号倉庫（デザインギャラリー）","kana":"かみかわそうこじゅうごうそうこ（でざいんぎゃらりー）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.76250328,"lng":142.36365104,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木骨煉瓦造平屋建、鉄板葺、建築面積231㎡","structure_material":"木骨煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0043","desc":"明治３１年に開業した鉄道駅構内に面する。通路を挟んで三号倉庫に直角に取り付き，現在ギャラリーとして活用されている。外壁煉瓦長手積とし，蛇腹に２段の歯飾りを設ける。鉄道の発展に伴い敷地が整えられた上川倉庫群の歴史を物語る重要な建造物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002496"},{"id":"00002493","register_sub_id":"101","register_pk":"103483","name":"上川倉庫二号倉庫（リハーサルホール）","kana":"かみかわそうこにごうそうこ（りはーさるほーる）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.76280838,"lng":142.36361931,"geo_status":"db","era":"明治33","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木骨煉瓦造平屋建、鉄板葺、建築面積165㎡","structure_material":"木骨煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0040","desc":"妻側で通りに面し敷地の北角を占める。一号倉庫と同規模の木骨煉瓦造倉庫で，敷地内平側中央に４枚厚の３心円アーチからなる入口と，その左右に欠円アーチの開口部を設ける。倉庫群中，最初に完成した建造物で，現在音楽の稽古場として活用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002493"},{"id":"00002495","register_sub_id":"101","register_pk":"103485","name":"上川倉庫八号倉庫","kana":"かみかわそうこはちごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"北海道","address":"北海道旭川市宮下通11丁目1604-1・2","lat":43.76269279,"lng":142.36416124,"geo_status":"db","era":"明治37","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木骨煉瓦造平屋建、瓦葺一部鉄板葺、建築面積165㎡","structure_material":"木骨煉瓦造平屋建","registered":"2001.11.20(平成13.11.20)","register_no":"01 － 0042","desc":"宮下通に面し事務所東側に隣接する。切妻造，瓦葺一部鉄板葺，外観イギリス積で，隅部に焼過ぎ煉瓦で柱型をつくり，一号倉庫と類似した規模，外観をもつ。事務所と対照的な重厚かつ連続的外観を一号倉庫と共に構成し，近代的街路景観の形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002495"},{"id":"00001461","register_sub_id":"101","register_pk":"102451","name":"旧丹波屋旅館洋館","kana":"きゅうたんばやりょかんようかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道枝幸郡中頓別町字小頓別91-1","lat":44.82787447,"lng":142.30438782,"geo_status":"db","era":"昭和2頃","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、亜鉛メッキ鋼板葺、建築面積50㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"01 － 0017","desc":"国道２７５号線に面し，和館の東妻面に接続して建つ。寄棟小屋根の両端を切り落とした腰折屋根が特徴的な木造２階建，屋根裏部屋付き，下見板張の洋館で，縦長窓の上部にスティックワークにより扁平アーチのファンライトを造りだしている点にも特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001461"},{"id":"00001460","register_sub_id":"101","register_pk":"102450","name":"旧丹波屋旅館和館","kana":"きゅうたんばやりょかんわかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道枝幸郡中頓別町字小頓別91-1","lat":44.82787996,"lng":142.30436158,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、亜鉛メッキ鋼板葺、建築面積102㎡","structure_material":"木造2階建","registered":"2000.02.15(平成12.02.15)","register_no":"01 － 0016","desc":"宗谷本線音威子府駅から分岐してオホーツク回りで稚内に至る旧天北線の小頓別駅の駅前旅館。主屋としての和館は小頓別駅開業時に合わせて建設されたもの。木造２階建，切妻屋根，平入で，正面中央に切妻破風の玄関を設け，階上を客室に充てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001460"},{"id":"00002576","register_sub_id":"101","register_pk":"103566","name":"旧北陸銀行江別支店","kana":"きゅうほくりくぎんこうえべつしてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道江別市二条2-6","lat":43.11358538,"lng":141.55917472,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"石造2階建、鉄板葺、建築面積57㎡","structure_material":"石造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"01 － 0048","desc":"江別駅近くの商業中心地にある銀行建築で，現在は喫茶店として活用されている。切妻造・平入で，正面に下屋庇とポーチを設けた形式で，構造は石造，小屋組はキングポストトラスである。土蔵造風の外観は，地方における銀行の支店建築に通じている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002576"},{"id":"00014445","register_sub_id":"101","register_pk":"512429","name":"銀鱗荘旧本館（旧猪俣家住宅）","kana":"ぎんりんそうきゅうほんかん（きゅういのまたけじゅうたく）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道小樽市桜一丁目1-2他","lat":43.18067778,"lng":141.03493333,"geo_status":"db","era":"明治後期／昭和13年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造3階建、瓦葺、建築面積420㎡","structure_material":"木造3階建","registered":"2023.02.27(令和5.02.27)","register_no":"01 - 0163","desc":"石狩湾を望む丘陵の一角に建つ。開道70年を機に移築した旧鰊漁家と、サンルーム等を備えた地階付平屋の増築部よりなる。移築部は木造二階建、平入、望楼付で、内部に二間半の神棚を祀る六間取り広間を設ける。豪壮な漁家建築を核とする近代の旅館施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014445"},{"id":"00014446","register_sub_id":"101","register_pk":"512430","name":"グリル銀鱗荘（旧北海道水産記念館）","kana":"ぐりるぎんりんそう（きゅうほっかうどうすいさんきねんかん）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"北海道","address":"北海道小樽市桜一丁目1-2他","lat":43.18048056,"lng":141.03474722,"geo_status":"db","era":"明治後期／昭和16年移築、同44年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積259㎡","structure_material":"木造2階建","registered":"2023.02.27(令和5.02.27)","register_no":"01 - 0164","desc":"銀鱗荘旧本館の西側に北面して建つ。鰊の一時保管に用いた「廊下」を移築し、水産記念館として改装したもの。木造二階建、寄棟造妻入で、外装漆喰塗とし四周の窓を虫籠窓風とする外観と太い軸部が重厚。本館と共に北海道水産業の繁栄を物語る記念碑的な建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014446"},{"id":"00000115","register_sub_id":"101","register_pk":"101105","name":"五島軒本店旧館","kana":"ごとうけんほんてんきゅうかん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"北海道","address":"北海道函館市末広町4-13","lat":41.76350076,"lng":140.7162289,"geo_status":"db","era":"昭和9","year":1934,"year_source":"db","year_min":1934,"year_max":1934,"year_label":null,"structure":"木造・鉄筋コンクリート造2階建，亜鉛板葺，建築面積1865㎡","structure_material":"木造・鉄筋コンクリート造2階建","registered":"1997.05.07(平成9.05.07)","register_no":"01 － 0002","desc":"昭和９年の大火の後に再建された木造及び鉄筋コンクリート造，２階建のレストランで，亀井勝二郎・竹下茂の設計と伝える。質素な外観と対照的な高い腰壁・落ちついた色調の布壁でまとめた格調高い内装に特徴があり，結婚式場にも利用され広く知られている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000115"},{"id":"00015270","register_sub_id":"101","register_pk":"532394","name":"さっぽろテレビ塔","kana":"さっぽろてれびとう","category":"産業3次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"北海道","address":"北海道札幌市中央区大通西一丁目1他","lat":43.06111389,"lng":141.35644444,"geo_status":"db","era":"昭和32年／昭和38年改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"鉄骨造及び鉄筋コンクリート造、高さ144m、脚間35m、地下2階付","structure_material":"鉄骨造及び鉄筋コンクリート造","registered":"2025.03.13(令和7.03.13)","register_no":"01 - 0171","desc":"大通公園の東端に位置し、電波発信及び観光拠点の機能を担う自立式鉄塔。総高一四四メートル、末広がりの立面形状で、四隅でトラスを三角錐状に組み、上下に展望台を設けた全一四節の主塔部とアンテナを支持する鉄塔部からなる。札幌を代表するランドマーク。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015270"},{"id":"00004684","register_sub_id":"101","register_pk":"105674","name":"函館大手町ハウス（旧浅野セメント函館営業所）","kana":"はこだておおてまちはうす（きゅうあさのせめんとはこだてえいぎょうしょ）","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"北海道","address":"北海道函館市大手町5-1","lat":41.77050806,"lng":140.7232207,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、銅板葺、建築面積139㎡","structure_material":"木造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"01 － 0062","desc":"木造２階建で，正面両脇を突出して塔状に扱い，コンクリートブロックで隅柱を表す。正面入口にファンライトを飾り，アーケード上をバルコニーとする。窓庇と窓台は直線的な意匠。棟札から棟梁は村木甚三郎。平成１６年の改修工事で往時の外観に整備された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004684"},{"id":"00011612","register_sub_id":"101","register_pk":"210628","name":"宮本商産旧本社ビル","kana":"みやもとしょうさんきゅうほんしゃびる","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"北海道","address":"北海道帯広市西二条南五丁目1他","lat":42.926993,"lng":143.201273,"geo_status":"db","era":"大正8年","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積91㎡","structure_material":"木造2階建","registered":"2017.06.28(平成29.06.28)","register_no":"01-0149","desc":"駅前通りの角地に建つ木造二階建の社屋。東正面は煉瓦タイル貼とし、二層分の柱形を配して花崗岩の帯を廻らす。壁頂にコーニスとデンティルを廻らし、正面中央にペディメントを飾るなど、重厚な趣を見せる。戦前の帯広の繁栄を伝える良質な事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011612"},{"id":"00003775","register_sub_id":"101","register_pk":"104765","name":"青森県立郷土館（旧青森銀行本店）","kana":"あおもりけんりつきょうどかん（きゅうあおもりぎんこうほんてん）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"青森県","address":"青森県青森市本町2-8-14","lat":40.82729533,"lng":140.74885468,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積750㎡","structure_material":"鉄筋コンクリート造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"02 － 0026","desc":"第五十九銀行青森支店として建設。鉄筋コンクリート造２階建の銀行建築で，吹抜の営業室にはフラットスラブ風の柱頭を持つ８本の円柱を建て，ギャラリーを廻す。古典主義建築の骨格を保持しつつ細部装飾を省略したモダニズム建築の一例。設計は堀江幸治。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003775"},{"id":"00009111","register_sub_id":"101","register_pk":"164664","name":"石場旅館","kana":"いしばりょかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"青森県","address":"青森県弘前市大字元寺町55","lat":40.60559146,"lng":140.46969264,"geo_status":"db","era":"明治12年／明治中期増築・昭和30年頃・昭和45年改修","year":1879,"year_source":"db","year_min":1879,"year_max":1879,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積456㎡","structure_material":"木造2階建","registered":"2012.02.23(平成24.02.23)","register_no":null,"desc":"通り西側に建つ。妻入の2階建、建築面積456平方メートル。東西棟の入母屋造鉄板葺2棟を雁行させる。南側を前方に出し、玄関やフロントを配し、後方に土蔵を附属し、北奥の棟に広間や客室を設ける。屋号をあしらうガラスや欄干が、老舗旅館の風情を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009111"},{"id":"00003342","register_sub_id":"101","register_pk":"104332","name":"旧高谷銀行本店（盛農薬商会倉庫）","kana":"きゅうたかやぎんこうほんてん（もりのうやくしょうかいそうこ）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県つがる市木造千代町34-2","lat":40.80827949,"lng":140.38607317,"geo_status":"db","era":"大正初期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正初期","structure":"木造2階建、鉄板葺、建築面積91㎡","structure_material":"木造2階建","registered":"2003.07.01(平成15.07.01)","register_no":"02 － 0022","desc":"町中心部，木造駅を起点とする表通りに面する敷地に建つ。正面中央に，規模と意匠の異なる円柱に挟まれた入口を設け，その上部及び左右に，高密度な浅彫をあしらった窓及び屋根窓を設ける。様式に拘らない自由で独特なデザインが特徴。堀江組の設計施工。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003342"},{"id":"00003341","register_sub_id":"101","register_pk":"104331","name":"旧弘前無尽社屋（三上ビル）","kana":"きゅうひろさきむじんしゃおく（みかみびる）","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"青森県","address":"青森県弘前市大字元寺町9","lat":40.60341924,"lng":140.469711,"geo_status":"db","era":"昭和2","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"鉄筋コンクリート造3階一部4階建、建築面積109㎡","structure_material":"鉄筋コンクリート造3階一部4階建","registered":"2003.07.01(平成15.07.01)","register_no":"02 － 0021","desc":"弘前公園東方に位置する。弘前市内初期の鉄筋コンクリート造建造物で，設計は青森工業学校長の大竹巽。角地の隅を切り垂直性を強調した壁面を立ち上げ，３階窓上部にあしらった歯飾状装飾を背面にまで連続させるなどアールデコ調の意匠に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003341"},{"id":"00000232","register_sub_id":"101","register_pk":"101222","name":"佐滝本店","kana":"さたきほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"青森県","address":"青森県三戸郡三戸町大字八日町49","lat":40.37723463,"lng":141.25649929,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄筋コンクリート造2階建，建築面積99㎡","structure_material":"鉄筋コンクリート造2階建","registered":"1997.07.15(平成9.07.15)","register_no":"02 － 0001","desc":"南部地方における鉄筋コンクリート造の先駆け的な建物。近年２階正面が改修され、蔦に覆われたかつてのおもむきが一新された。塔屋風の屋根飾りを持ち当時流行したドイツ表現派の影響が見られる構成となる。設計施工は弘前の堀江組。側面にアーチ門が付設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000232"},{"id":"00006116","register_sub_id":"101","register_pk":"107100","name":"新むつ旅館本館","kana":"しんむつりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"青森県","address":"青森県八戸市小中野六丁目110-1","lat":40.519657,"lng":141.518463,"geo_status":"db","era":"明治30頃","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積177㎡","structure_material":"木造2階建","registered":"2007.05.15(平成19.05.15)","register_no":"02 － 0052","desc":"八戸市中心部の小中野新地に所在。桁行６間規模，切妻造，鉄板葺，平入の木造２階建で，２階に３列５室の客室を配す。中央に天窓を開けた吹抜と洋風意匠のＹ字状階段を設け，たちが高く，１階軒先部の細工や２階軒の出桁上に照明を付けた独特のつくりに特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006116"},{"id":"00011839","register_sub_id":"101","register_pk":"354911","name":"ヤマニ仙遊館土蔵","kana":"やまにせんゆうかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"青森県","address":"青森県南津軽郡大鰐町大字蔵館字村岡47","lat":40.521448,"lng":140.575718,"geo_status":"db","era":"明治30年頃／昭和中期・同56年改修","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、鋼板葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"02-104","desc":"本館の北西側に建つ。建築面積五〇平方メートル、土蔵造二階建、銅板葺で、外壁は一階を石張風に、二階を漆喰塗とする。屋根は置屋根形式とし、街路に面した北面に二階には小ぶりな窓を開き、庇をかける。温泉街のかつての景観を今に伝える建物である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011839"},{"id":"00011838","register_sub_id":"101","register_pk":"354910","name":"ヤマニ仙遊館本館","kana":"やまにせんゆうかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"青森県","address":"青森県南津軽郡大鰐町大字蔵館字村岡47","lat":40.521284,"lng":140.575853,"geo_status":"db","era":"明治30年頃／昭和中期・同56年改修","year":1897,"year_source":"converted","year_min":1897,"year_max":1897,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積328㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"02-103","desc":"平川沿いに南面して建つ旅館。建築面積三二八平方メートル、木造二階建鋼板葺で、北面中央に玄関を開き、左方に座敷等を、右方に帳場等を配す。玄関奥の階段を上がった二階には、東西に中廊下を通して南北に客室を並べる。大鰐温泉の往時の景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011838"},{"id":"00014556","register_sub_id":"101","register_pk":"515098","name":"旧高善旅館（柳翁宿）","kana":"きゅうたかぜんりょかん（りゅうおうじゅく）","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"岩手県","address":"岩手県遠野市中央通り2-11","lat":39.32921111,"lng":141.52856111,"geo_status":"db","era":"明治前期／明治39年・大正5年増築、昭和23年改修、昭和60年移築、平成25年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、瓦葺、建築面積243㎡","structure_material":"木造2階建","registered":"2023.08.07(令和5.08.07)","register_no":"03 - 0120","desc":"遠野屈指の旅館で元は城下中心地にあり要人が宿泊した。東側切妻造に明治後期に西側入母屋造を増築。東側は通り土間・広いミセ・吹抜常居を並べた遠野の典型町家。西側は起り屋根石敷玄関を構えて正面を大階段とし、二階に床構え付客室を配した近代和風旅館。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014556"},{"id":"00007830","register_sub_id":"101","register_pk":"108811","name":"黒沢治助商店一番蔵及び二番蔵","kana":"くろさわちすけしょうてんいちばんぐらおよびにばんぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27407897,"lng":141.30121624,"geo_status":"db","era":"大正7／昭和6・昭和43改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積175㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"03-0077","desc":"主屋の東南に東西棟で建つ。桁行１９ｍ梁間７．２ｍと規模の大きい土蔵造２階建で、北面に庇を付ける。外壁は白漆喰仕上げを基調に、腰を海鼠壁とし、鉢巻や両開の掛子塗戸は角を白漆喰とする黒漆喰仕上げ。重厚で、丁寧な仕上げになる外観は見応えがある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007830"},{"id":"00007831","register_sub_id":"101","register_pk":"108812","name":"黒沢治助商店穀物蔵","kana":"くろさわちすけしょうてんこくもつぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27408271,"lng":141.30143795,"geo_status":"db","era":"昭和前期／昭和後期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、鉄板葺、建築面積93㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"03-0078","desc":"一番蔵及び二番蔵の東に東西棟で建つ。桁行１３ｍ梁間５．５ｍの木造２階建。切妻造鉄板葺で、北面に庇を付ける。現在は白漆喰塗とし、開口に鉄扉を吊る。内部は板壁で、トラス組。１階は一室、２階は階段室と三室に間仕切り、穀物など食料を保管した。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007831"},{"id":"00007828","register_sub_id":"101","register_pk":"108809","name":"黒沢治助商店主屋","kana":"くろさわちすけしょうてんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27422139,"lng":141.30075991,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積119㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"03-0075","desc":"敷地北辺の中央に東西棟で建つ。木造平屋建の切妻造桟瓦葺で、西面下屋南寄りに、切妻屋根を付け、袖塀を設け、出入口とする。漆喰仕上げの大壁造とし、雨戸も外側を漆喰仕上げの上に銅板を張る。南側に通り土間を設け、ジョウイ等を配する。重厚で、力強い外観。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007828"},{"id":"00007832","register_sub_id":"101","register_pk":"108813","name":"黒沢治助商店倉庫","kana":"くろさわちすけしょうてんそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27412365,"lng":141.30060025,"geo_status":"db","era":"昭和前期／昭和後期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、鉄板葺、建築面積129㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"03-0079","desc":"敷地前寄り、店舗の南に建つ。東西２３ｍの長い木造２階建。２階正面は、間口６．４ｍで、柱形を現し、三分して各間に鉄扉を吊る。１階は庇を付け、大きく開口を設け、銅板張雨戸をたてる。壁は人造石洗出し仕上げ。伝統的な意匠の店舗と鮮やかな対比を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007832"},{"id":"00007827","register_sub_id":"101","register_pk":"108808","name":"黒沢治助商店店舗","kana":"くろさわちすけしょうてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27419605,"lng":141.30054032,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造2階建、瓦葺、建築面積100㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"03-0074","desc":"通りの東側に占める短冊形の敷地の西正面に建つ。桁行８．５ｍ梁間１２ｍ、木造２階建、切妻造桟瓦葺の町家で、軒などを塗り込める。１階に事務室などを配し、２階に十五畳と二十畳の座敷を設け、座敷飾りを構える。良材や大材を多く用い、質の高い意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007827"},{"id":"00007834","register_sub_id":"101","register_pk":"108815","name":"黒沢治助商店防火塀","kana":"くろさわちすけしょうてんぼうかべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27408592,"lng":141.30057878,"geo_status":"db","era":"大正後期・昭和20頃","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"煉瓦造、延長45m","structure_material":"煉瓦造","registered":"2009.11.02(平成21.11.02)","register_no":"03-0081","desc":"敷地前方の南辺と北辺に築かれる。北辺は高さ２．７ｍ厚さ３８㎝延長６．８ｍ、煉瓦造で、敷地内側を人造石洗出し仕上げとする。南辺は煉瓦を内外とも現し、前方２８ｍを高さ３．７ｍに、後方１０ｍを高さ２．７ｍに積む。防火に対する意識の高さが窺われる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007834"},{"id":"00007833","register_sub_id":"101","register_pk":"108814","name":"黒沢治助商店門及び石塀","kana":"くろさわちすけしょうてんもんおよびいしべい","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27414799,"lng":141.30041083,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"門 石造、間口3.6m、 塀 石造、延長7.2m","structure_material":"門 石造","registered":"2009.11.02(平成21.11.02)","register_no":"03-0080","desc":"店舗の正面、通り沿いに位置する。高さ２．６ｍ、３７㎝角の御影石の石柱を間口３．６ｍに建て、門とする。門柱から通りに沿って江戸切仕上げの御影石を積み、上部に笠石を置く。高さ９０㎝厚さ３０㎝で、延長７．２ｍ。敷地正面において、屋敷構えを整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007833"},{"id":"00007829","register_sub_id":"101","register_pk":"108810","name":"黒沢治助商店渡廊下","kana":"くろさわちすけしょうてんわたりろうか","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"岩手県","address":"岩手県二戸市福岡字中町6他","lat":40.27424504,"lng":141.30065687,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋建、瓦葺、建築面積21㎡","structure_material":"木造平屋建","registered":"2009.11.02(平成21.11.02)","register_no":"03-0076","desc":"店舗と主屋を繋ぐ。桁行８．５ｍ梁間２．４ｍの木造平屋建、東西棟の桟瓦葺とする。南側を廊下とし、北側に便所や洗面所、物入を配する。南面は腰にタイルを貼り、上部に窓を連続して開け、軒や戸袋を塗り込める。雨戸は漆喰仕上げ銅板張の防火戸とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007829"},{"id":"00016465","register_sub_id":"101","register_pk":"574827","name":"鉛温泉藤三旅館白猿の湯","kana":"なまりおんせんふじさんりょかんしろさるのゆ","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県花巻市鉛字中平75-1他","lat":39.46231083,"lng":140.99528194,"geo_status":"db","era":"昭和前期／平成16年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造地上1階地下1階建、鉄板葺、建築面積109㎡","structure_material":"木造地上1階地下1階建","registered":"2026.02.10(令和8.02.10)","register_no":"03 - 0129","desc":"本館の東方に位置する浴室棟。平屋建寄棟造鉄板葺で棟中央に越屋根を設ける。二箇所の入口から石段で地階の浴場に至り、中央に岩盤を刳抜いた深さ約一・三メートルの大浴槽を配する。浴槽周囲は石敷床に石壁で重厚に仕上げ、上部を吹抜とした開放的な浴室棟。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016465"},{"id":"00016464","register_sub_id":"101","register_pk":"574826","name":"鉛温泉藤三旅館本館","kana":"なまりおんせんふじさんりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"岩手県","address":"岩手県花巻市鉛字中平75-1他","lat":39.46231083,"lng":140.99528194,"geo_status":"db","era":"昭和16年／昭和39年増築","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造3階建、瓦葺一部鉄板葺、建築面積607㎡","structure_material":"木造3階建","registered":"2026.02.10(令和8.02.10)","register_no":"03 -0128","desc":"鉛温泉に位置する旅館。豊沢川沿いに建つ木造三階建で、南東に座敷棟を接続する。南面東寄りに唐破風造の玄関を突出し、上部を楼閣風につくり入母屋屋根を付す。内部は各階中廊下の南北に客室を並べる。川に面した大規模な三階建旅館が温泉地の風情を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016464"},{"id":"00012082","register_sub_id":"101","register_pk":"352881","name":"花巻温泉旧松雲閣別館","kana":"はなまきおんせんきゅうしょううんかくべっかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"low","period":"昭和前","pref":"岩手県","address":"岩手県花巻市湯本第1地割他","lat":39.45369,"lng":141.068657,"geo_status":"db","era":"昭和2年／昭和14年・同36年増築","year":1927,"year_source":"db","year_min":1927,"year_max":1927,"year_label":null,"structure":"木造2階建、瓦葺、建築面積957㎡","structure_material":"木造2階建","registered":"2018.03.27(平成30.03.27)","register_no":"03-102","desc":"木造二階建の大規模旅館建築。桁行五五・五メートル、梁間一六・三メートルで、南正面中央やや右寄りに玄関を開き、一、二階とも中廊下を通して南、東に客間を配し、背面側には広間等を置く。屋根は赤色の釉薬瓦で葺き、花巻温泉の往時の景観を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012082"},{"id":"00011033","register_sub_id":"101","register_pk":"205140","name":"萬代舘","kana":"ばんだいかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"岩手県","address":"岩手県二戸郡一戸町一戸字本町49","lat":40.217532,"lng":141.302421,"geo_status":"db","era":"昭和31／平成20改修","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積374㎡","structure_material":"木造平屋一部2階建","registered":"2016.08.01(平成28.08.01)","register_no":"03 - 0086","desc":"一戸の中心地、馬淵川を渡るメインストリートの突当りに建つ。正面は下部をタイル貼、上部をモルタル塗りとし、内部は玄関を入って左右に階段を設け、一部二階を設ける総椅子式としている。高度成長期以前に全国で多数建設された映画館の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011033"},{"id":"00011038","register_sub_id":"101","register_pk":"205145","name":"一條旅舘土蔵","kana":"いちじょうりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県白石市福岡蔵本字鎌先一番40-1","lat":38.024403,"lng":140.574838,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積41㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"04 - 0125","desc":"敷地最奥部、一段高い位置に建つ。桁行五間、梁間二間半の土蔵造で、屋根は置屋根鉄板葺。外壁は腰下見板張上部は白漆喰塗とする。背面側のみ三尺、他は一尺五寸間隔で柱を建てる。北側正面には庇を設け、扉は土扉、板戸、格子戸の三重とするなど質が高い。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011038"},{"id":"00011036","register_sub_id":"101","register_pk":"205143","name":"一條旅舘木造本館","kana":"いちじょうりょかんもくぞうほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県白石市福岡蔵本字鎌先一番40-4","lat":38.024882,"lng":140.575104,"geo_status":"db","era":"昭和16","year":1941,"year_source":"db","year_min":1941,"year_max":1941,"year_label":null,"structure":"木造3階一部地下1階建、鉄板葺、建築面積228㎡","structure_material":"木造3階一部地下1階建","registered":"2016.08.01(平成28.08.01)","register_no":"04 - 0123","desc":"白石市郊外の鎌先温泉の湯治宿。昭和一二年の豪雨被害の後に建て替えられたもの。一階から三階まで四周に廊下を廻らし、八畳、六畳、四畳半の座敷が全一〇室並ぶ。高欄と木製建具を連ねる瀟洒な外観のみならず、スギの良材を多用し過半を通し柱とする点も特徴。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011036"},{"id":"00011037","register_sub_id":"101","register_pk":"205144","name":"一條旅舘湯向棟","kana":"いちじょうりょかんゆむかいとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県白石市福岡蔵本字鎌先一番40-4","lat":38.024672,"lng":140.574947,"geo_status":"db","era":"昭和8","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積294㎡","structure_material":"木造2階建","registered":"2016.08.01(平成28.08.01)","register_no":"04 - 0124","desc":"鎌先温泉は正長元年開湯と伝える古くからの湯治場で、一條旅舘はその細長い谷戸の奥に位置する。湯向棟は木造本館と同じく各階に四周に廊下を廻らし、八畳、六畳の座敷を全八室並べる。昭和初期の大規模木造建築の好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011037"},{"id":"00002582","register_sub_id":"101","register_pk":"103572","name":"老松永田醸造店舗","kana":"おいまつながたじょうぞうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県亘理郡亘理町字上町31","lat":38.03231648,"lng":140.85411576,"geo_status":"db","era":"明治20代","year":1887,"year_source":"converted","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造2階建、瓦葺、建築面積94㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"04 － 0038","desc":"亘理町中心部にある醸造業の老舗で，店舗は街道に東面して建つ。２階建，切妻造・桟瓦葺，平入で，下屋庇を設けた桁行南４間をミセ，北２間を袖蔵とした構成である。正面２階は壁を海鼠壁とし，小庇の持送り，観音扉や棟積など全体に重厚なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002582"},{"id":"00011444","register_sub_id":"101","register_pk":"210404","name":"岡崎旅館別館北棟","kana":"おかざきりょかんべっかんきたとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉4-7","lat":38.145976,"lng":140.534399,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造2階建、鋼板葺、建築面積140㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"04-0126","desc":"青根温泉の中心に位置する。東西棟で建つ木造二階建、寄棟造鋼板葺で、内部は一〇畳間の座敷を三室並べ、東・北面に廊下を廻らし、北西部に八畳間の張出しを設ける。障子や欄間に精密な細工を凝らし、縁側のガラス戸や手摺りの組子により、独特の外観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011444"},{"id":"00011445","register_sub_id":"101","register_pk":"210403","name":"岡崎旅館別館南棟","kana":"おかざきりょかんべっかんみなみとう","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉4-7","lat":38.145804,"lng":140.534533,"geo_status":"db","era":"明治中期／平成23年改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、鋼板葺、建築面積230㎡","structure_material":"木造2階建","registered":"2017.05.02(平成29.05.02)","register_no":"04-0127","desc":"別館北棟に矩折れに南接して建つ。木造二階建、寄棟造、鋼板葺。内部は一、二階とも中廊下を挟み大小の座敷を全二〇室並べ、東・南面に廊下を廻らす。小屋組は和小屋である。内部の保存状態が良く、青根温泉において、明治三九年大火前の風情を伝える旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011445"},{"id":"00003048","register_sub_id":"101","register_pk":"104038","name":"男山本店店舗","kana":"おとこやまほんてんてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県気仙沼市魚町2-2-14","lat":38.90641004,"lng":141.57432362,"geo_status":"db","era":"昭和6頃","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造3階建、鉄板葺、建築面積173㎡","structure_material":"木造3階建","registered":"2003.01.31(平成15.01.31)","register_no":"04 － 0045","desc":"木筋コンクリート造・３階建の店舗建築で，気仙沼湾最奥の内湾をほぼ南に望んで建つ。洗い出し仕上の外壁は，各階に蛇腹を廻し，パラペットは柱型や欄干及びゲーブルなどで飾るなど，際だった存在である。市内魚町にあって，昭和初期の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003048"},{"id":"00003046","register_sub_id":"101","register_pk":"104036","name":"角星店舗","kana":"かくぼしてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県気仙沼市魚町2-1-9","lat":38.90628642,"lng":141.57384104,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積99㎡","structure_material":"土蔵造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"04 － 0043","desc":"気仙沼湾最奥の内湾に面した魚町にあり，通りに面して建つ。木造・２階建，切妻造・桟瓦葺の土蔵造であるが，敷地形状に合わせた不等辺四角形の平面のため，両側の柱や出梁及び垂木などを平行四辺形に木取りするなど，希少な大工技術を用いた繊細な店舗建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003046"},{"id":"00013477","register_sub_id":"101","register_pk":"504845","name":"旧菅野屋勘兵衛（廻船問屋菅勘資料館）主屋","kana":"きゅうかんのやかんべえ（かいせんどんやかんかんしりょうかん）おもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池中町24-1","lat":38.65154722,"lng":141.28010278,"geo_status":"db","era":"明治22年頃／昭和48年、平成20年改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積110㎡","structure_material":"木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0182","desc":"市内中心部にある廻船問屋を営んだ商家。主屋は、道路に南面する店舗の背面に接続して建つ。木造平屋建、切妻造鉄板葺で、東、北面に下屋を廻し、北面西端に便所を付す。内部は一列四室とし、最奥を床付の座敷とする。庭に向けて開放的なつくりを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013477"},{"id":"00013479","register_sub_id":"101","register_pk":"504847","name":"旧菅野屋勘兵衛（廻船問屋菅勘資料館）穀蔵","kana":"きゅうかんのやかんべえ（かいせんどんやかんかんしりょうかん）こくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池中町24-1","lat":38.65167778,"lng":141.280225,"geo_status":"db","era":"明治32年頃／平成20年改修","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0184","desc":"文庫蔵東側に南面して建つ二階建の土蔵造桟瓦葺で、妻入正面に下屋、二階に鳥居形枠窓を開く。外壁は漆喰で軒先まで塗込めて鉢巻を廻し、腰と下屋との取合を海鼠壁とする。内部は漆喰塗で和小屋を現す。文庫蔵よりやや簡素ながら敷地景観に重厚さを加える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013479"},{"id":"00013478","register_sub_id":"101","register_pk":"504846","name":"旧菅野屋勘兵衛（廻船問屋菅勘資料館）文庫蔵","kana":"きゅうかんのやかんべえ（かいせんどんやかんかんしりょうかん）ぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県登米市登米町登米字寺池中町24-1","lat":38.65169444,"lng":141.28016111,"geo_status":"db","era":"明治23年","year":1890,"year_source":"db","year_min":1890,"year_max":1890,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積29㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0183","desc":"主屋北側に南面して建つ。二階建の土蔵造桟瓦葺で、妻入の正面に下屋、二階窓上に大振りの庇を付す。外壁は漆喰で軒先まで塗込めて鉢巻を廻し、腰、下屋との取合、軒下を海鼠壁とする。内部は漆喰塗で二重梁の和小屋を現す。重厚な敷地景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013478"},{"id":"00013487","register_sub_id":"101","register_pk":"504855","name":"旧佐忠商店（冨谷宿）店舗及び主屋","kana":"きゅうさちゅうしょうてん（とみやじゅく）てんぽおよびおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県富谷市富谷新町35","lat":38.39911667,"lng":140.88798056,"geo_status":"db","era":"明治後期／昭和20年代・同50年代改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階及び木造平屋建、瓦葺及び銅板葺、建築面積141㎡","structure_material":"土蔵造2階及び木造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0192","desc":"奥州街道富谷宿にある商家。街道に南面して建つ土蔵造桟瓦葺の店舗は、正面に下屋を付し、背後に切妻造銅板葺の主屋が接続する。店舗正面外観は、白漆喰塗と海鼠壁の外壁上部に黒漆喰塗の鉢巻三段を廻し、扇垂木風の軒とする。重厚感ある街道景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013487"},{"id":"00013488","register_sub_id":"101","register_pk":"504856","name":"旧佐忠商店（冨谷宿）門","kana":"きゅうさちゅうしょうてん（とみやじゅく）もん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県富谷市富谷新町35","lat":38.39905,"lng":140.88808333,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口3.9m","structure_material":"木造","registered":"2021.02.04(令和3.02.04)","register_no":"04 － 0193","desc":"店舗正面東側に建つ門。本柱上に冠木を渡して扉を開き、冠木に束を立てて棟木を受け、束から腕木を出して軒の深い切妻屋根を支える。本柱の外側に柱を立てて棟木を受け、両潜戸を開く。壁は漆喰塗とし、冠木上には欄間を飾る。店舗と共に街道景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013488"},{"id":"00012685","register_sub_id":"101","register_pk":"367589","name":"旧平野本店店舗兼主屋","kana":"きゅうひらのほんてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県気仙沼市新町70","lat":38.90690278,"lng":141.565515,"geo_status":"db","era":"大正10年頃／昭和8年頃増築、昭和38年頃改修","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造2階建、金属板葺、建築面積116㎡","structure_material":"木造2階建","registered":"2019.03.29(平成31.03.29)","register_no":"04 － 167","desc":"東浜街道と気仙沼街道が合流する角地に東面して建つ木造二階建で、南の洋風建築の店舗と北の寄棟造鉄板葺の住宅からなる。店舗は二階に半円アーチ窓を並べ、大ぶりのパラペットを立ち上げるなど華やかに仕上げる。地域のランドマークとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012685"},{"id":"00005219","register_sub_id":"101","register_pk":"106207","name":"三事堂ささ木店舗及び住宅","kana":"さんじどうささきてんぽおよびじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県気仙沼市八日町2-3-27","lat":38.90546576,"lng":141.57241467,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"木造2階建、鉄板葺、建築面積143㎡","structure_material":"木造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"04 － 0053","desc":"間口５間，奥行３間２尺の２階建店舗に，奥行３間半の２階建住宅が接続する。屋根は寄棟造の鉄板葺である。正面１階は改修されているが，２階窓は櫛形ペディメントと窓台で洋風に飾る。ガラス窓桟割も技巧的である。外壁は２階軒裏までを白漆喰仕上げとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005219"},{"id":"00005220","register_sub_id":"101","register_pk":"106208","name":"三事堂ささ木土蔵","kana":"さんじどうささきどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県気仙沼市八日町2-3-27","lat":38.90719436,"lng":141.57133428,"geo_status":"db","era":"大正中期","year":1919,"year_source":"estimated","year_min":1916,"year_max":1922,"year_label":"大正中期","structure":"土蔵造2階建、瓦葺、建築面積25㎡","structure_material":"土蔵造2階建","registered":"2006.03.02(平成18.03.02)","register_no":"04 － 0054","desc":"桁行３間，梁間２間規模の土蔵造２階建で，道路側妻面の１，２階に窓を開く。屋根は切妻造の桟瓦葺で，１階に瓦葺庇を付ける。外壁は白漆喰塗である。南面中央，店舗内部に戸口を開き，漆喰塗の両開き土戸を釣り込む。小屋組は洋風トラスである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005220"},{"id":"00001993","register_sub_id":"101","register_pk":"102983","name":"庄子屋醤油店店舗及び住宅","kana":"しょうじやしょうゆてんてんぽおよびじゅうたく","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県仙台市青葉区八幡町4-222","lat":38.27012088,"lng":140.84917602,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積111㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"04 － 0032","desc":"仙台味噌醸造元の店舗住宅で国道４８号線に沿って南面して建つ。木造２階建，切妻造，桟瓦葺，平入，間口５間の店舗の背後に西に寄せて平屋建，寄棟造，桟瓦葺の住居部が取付く。仙台旧市街でも多くみられたセガイ造りの商家建築の型式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001993"},{"id":"00012870","register_sub_id":"101","register_pk":"368086","name":"壽丸屋敷主屋","kana":"すまるやしきしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県白石市字中町48-5他","lat":38.00383056,"lng":140.62306667,"geo_status":"db","era":"大正10年頃／昭和39年増築","year":1921,"year_source":"db","year_min":1921,"year_max":1921,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積338㎡","structure_material":"木造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 178","desc":"店蔵の背面に南面して建つ。入母屋造平屋建の正面東端に入母屋玄関を出し、東に洋風応接間、西に2列4室を配し、西面に角屋で上座敷棟を延ばす。東側に二階建の別棟を付し、一階に台所等、二階に居室を設ける。白石城下の商家の伝統的な構成を伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012870"},{"id":"00012869","register_sub_id":"101","register_pk":"368085","name":"壽丸屋敷店蔵","kana":"すまるやしきみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県白石市字中町48-5他","lat":38.00375833,"lng":140.62271944,"geo_status":"db","era":"明治後期／平成17年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積55㎡","structure_material":"土蔵造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 177","desc":"白石旧城下中心部のもと商家で、店蔵は街路に西面して建つ。切妻造の土蔵造二階建で、一階の窓に鉄製格子を嵌め、二階に観音扉付の二窓を穿つ。一階は前土間の店舗とし、二階に二室を設ける。重厚かつ均整の取れた外観で、旧城下の街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012869"},{"id":"00004493","register_sub_id":"101","register_pk":"105483","name":"武山米店店舗及び主屋","kana":"たけやまこめてんてんぽおよびしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県気仙沼市魚町1-1-13","lat":38.90693214,"lng":141.57292034,"geo_status":"db","era":"昭和5","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階建、亜鉛メッキ鋼板葺、建築面積115㎡","structure_material":"木造2階建","registered":"2005.02.09(平成17.02.09)","register_no":"04 － 0050","desc":"奥行に従い幅の狭まる不整形な敷地に建つ変形平面の町家。屋根は切妻造の鉄板葺で，正面の垂木を扇形に配するのが特徴。２階の腰壁と戸袋は銅板張である。１階は正面一杯を店舗とする。２階の座敷２室は，敷地の制約から台形平面をなす。背後に蔵が附属する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004493"},{"id":"00012871","register_sub_id":"101","register_pk":"506171","name":"玉幸","kana":"たまこう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県白石市字堂場前24他","lat":38.00490278,"lng":140.62471389,"geo_status":"db","era":"明治後期／大正14年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋一部2階建、瓦葺及び金属板葺、建築面積678㎡","structure_material":"木造平屋一部2階建","registered":"2019.09.10(令和1.09.10)","register_no":"04 － 179","desc":"市街地東部にある料亭。寄棟造の玄関棟北面に入母屋玄関を出し、東前方に居住棟を連ね、東背面と西面に入母屋造の東棟と西棟を接続する。東西2棟に客間計8室を並べ、居住棟に調理場等を配して一部二階建とする。戦前の町の賑わいを伝える大規模和風建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012871"},{"id":"00009870","register_sub_id":"101","register_pk":"196017","name":"丹六園店舗兼主屋","kana":"たんろくえんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県塩竈市宮町101","lat":38.31774624,"lng":141.01925448,"geo_status":"db","era":"大正3頃","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積124㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"04 － 0090","desc":"鹽竈神社門前町の角地に建つ菓子店で、入母屋造桟瓦葺である。接道する南面と東面は出桁造として軒を深め、重厚な外観を見せる。南からミセ、七畳、オカミ（座敷）、台所及び居間を並べる。南寄りに二階を設け、座敷を配する。門前町の歴史的景観を伝える商家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009870"},{"id":"00009873","register_sub_id":"101","register_pk":"196020","name":"千田家住宅石蔵","kana":"ちだけじゅうたくいしぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県気仙沼市南町2-122-1","lat":38.90557224,"lng":141.57244976,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"石造2階建、建築面積33㎡","structure_material":"石造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"04 － 0093","desc":"主屋の東側北寄りに東西棟で建つ。石造二階建で南に土蔵が接続する。「塩釜石」と称する凝灰岩を布積とする。窓の庇に幾何学形状の持送りを付け、軒蛇腹を人造石研出し仕上げとするなど凝った意匠である。前年の大火後に建てられ、耐火性を意識した石蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009873"},{"id":"00009871","register_sub_id":"101","register_pk":"196018","name":"千田家住宅主屋","kana":"ちだけじゅうたくしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県気仙沼市南町2-122-1","lat":38.90546576,"lng":141.57241467,"geo_status":"db","era":"昭和5頃","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造2階一部3階建、建築面積127㎡、車庫付","structure_material":"木造2階一部3階建","registered":"2014.04.25(平成26.04.25)","register_no":"04 － 0091","desc":"内湾地区の交差点に面して建ち、木造モルタル塗で外壁に水平の張出しを廻らせる。隅部分は円弧状平面で塔屋風に三階を設け、また煙突状の飾り窓を付けてアクセントとするなど、表現主義を取入れた特徴的な外観になり、地域のランドマークとして親しまれる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009871"},{"id":"00009872","register_sub_id":"101","register_pk":"196019","name":"千田家住宅土蔵","kana":"ちだけじゅうたくどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県気仙沼市南町2-122-1","lat":38.90552881,"lng":141.57253304,"geo_status":"db","era":"大正5頃／昭和8頃・平成23改修","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造2階建、鋼板葺、建築面積41㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"04 － 0092","desc":"主屋の東側に南北棟で建ち、北には石蔵が接続する。二段積の石積基礎の上に土台を廻し、柱を密に立てて貫で強固に固め、外壁はモルタル塗とする。当地区では昭和四年の大火を免れた希少な蔵であり、主屋とともに歴史的な街路景観を形成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009872"},{"id":"00013344","register_sub_id":"101","register_pk":"368432","name":"鳥山米穀店店舗兼主屋","kana":"とりやまべいこくてんてんぽけんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"宮城県","address":"宮城県仙台市宮城野区原町三丁目461","lat":38.26656667,"lng":140.90683611,"geo_status":"db","era":"明治7年頃／昭和53年・同61年・平成20年改修","year":1874,"year_source":"db","year_min":1874,"year_max":1874,"year_label":null,"structure":"木造二階一部平屋建、瓦葺、建築面積152㎡","structure_material":"木造二階一部平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"04 － 0180","desc":"仙台城下東隣の宿場町の原町で、石巻街道に南面して建つ。木造切妻造桟瓦葺で、二階建東西棟の店舗背面に平屋建の主屋が続く。店舗正面の一階下屋は、西半に格子を嵌め、東半中央間を出入口とする。内部に通り土間がないなど、旧仙台藩領の町家の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013344"},{"id":"00010252","register_sub_id":"101","register_pk":"199026","name":"不忘閣穀蔵","kana":"ふぼうかくこくぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.144905,"lng":140.53455,"geo_status":"db","era":"明治29年頃／平成18年改修","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造平屋建、鉄板葺、建築面積41㎡","structure_material":"土蔵造平屋建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0102","desc":"座敷蔵の北側に並び建つ。土蔵造、桁行九・一メートル梁間四・五メートル、文庫蔵と座敷蔵と一連の金属板葺の置屋根をかける。外壁は漆喰塗で鉢巻を廻らせ、腰を海鼠壁とし、東面中央に戸口と窓を設け、窓枠を黒漆喰で丁寧に仕上げて外観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010252"},{"id":"00010249","register_sub_id":"101","register_pk":"199023","name":"不忘閣御殿棟","kana":"ふぼうかくごてんとう","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.144192,"lng":140.534624,"geo_status":"db","era":"昭和7年","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造2階建、銅板葺、建築面積161㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0099","desc":"離れ北西隅に渡廊下で接続して建つ。木造二階建、入母屋造で北面と南面に千鳥破風を飾り、周囲にガラス窓と刎高欄を廻らす。一二畳半の主座敷は上段とし、上質な座敷飾、小組格天井張など高い格式を示す。旧藩主一門の宿泊を意図した、優美な意匠の旅館建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010249"},{"id":"00010251","register_sub_id":"101","register_pk":"199025","name":"不忘閣座敷蔵","kana":"ふぼうかくざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.144786,"lng":140.534579,"geo_status":"db","era":"明治29年頃","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積59㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0101","desc":"文庫蔵と穀蔵の間に並び建ち、一体的な置屋根をかける。土蔵造二階建、桁行一一メートル梁間五・五メートルである。東面に戸口を二箇所設け、外壁は漆喰塗で鉢巻を廻らせ、一階の腰及び二階東面の腰を海鼠壁とする。二階はもと居室で、逗留客に供された。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010251"},{"id":"00010248","register_sub_id":"101","register_pk":"199022","name":"不忘閣離れ","kana":"ふぼうかくはなれ","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.14405,"lng":140.534957,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、鉄板葺、建築面積225㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0098","desc":"本館の南側に渡廊下で接続する南北棟と、その南端から東に延びる東西棟からなる、く字形平面の木造二階建である。前庭に面して同形同大の客室を並べて開放的なガラス窓を開き、手摺を廻らして表情をつける。当地方における湯治場の様子を伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010248"},{"id":"00010250","register_sub_id":"101","register_pk":"199024","name":"不忘閣文庫蔵","kana":"ふぼうかくぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.1447,"lng":140.534612,"geo_status":"db","era":"明治29年","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積38㎡","structure_material":"土蔵造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0100","desc":"敷地北寄りに南北に直列する土蔵群の南端に建つ。土蔵造二階建、桁行八・三メートル梁間四・五メートルで、北側の座敷蔵、穀蔵と一体の置屋根をかける。東面を戸口とし外壁は漆喰塗で鉢巻を廻らせ、腰を海鼠壁とする。明治大火を免れた、歴史的価値のある土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010250"},{"id":"00010247","register_sub_id":"101","register_pk":"199021","name":"不忘閣本館","kana":"ふぼうかくほんかん","category":"産業3次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.144365,"lng":140.53485,"geo_status":"db","era":"明治40年","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積253㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"04-0097","desc":"青根温泉中心部に構える敷地の中央に南北棟で建つ。木造二階建で、正面中央に入母屋造の車寄、背面中央に休憩所の張出しを設ける。上下階とも中廊下を直交方向に通して平面を四分し、各室に異なる意匠の座敷飾を備える。堂々とした容姿が湯治場の情緒を醸す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010247"},{"id":"00010253","register_sub_id":"101","register_pk":"199027","name":"不忘閣門","kana":"ふぼうかくもん","category":"産業3次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県柴田郡川崎町青根温泉1-1","lat":38.14466204,"lng":140.53492024,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、鉄板葺、間口2.7m、左右袖塀付","structure_material":"木造","registered":"2014.12.19(平成26.12.19)","register_no":"04-0103","desc":"敷地東辺に構える棟門形式の門で、二・七メートルと広い間口をもつ。切妻造金属板葺で両脇に袖塀を付け、南側に潜戸を開く。木太い柱と冠木を組み、棟束と腕木で小屋を受ける。伊達家の湯別当を務めた当主佐藤家の由緒を伝え、風格ある屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010253"},{"id":"00001853","register_sub_id":"101","register_pk":"102843","name":"ゆさや旅館本館","kana":"ゆさかりょかんほんかん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"昭和前","pref":"宮城県","address":"宮城県大崎市鳴子温泉字湯元46-2、47、47-2","lat":38.74162779,"lng":140.71761638,"geo_status":"db","era":"昭和11","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積695㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"04 － 0030","desc":"鳴子温泉の発祥とされる「滝の湯」の湯守となった寛永９年創業の老舗旅館で，昭和１１年の改築。木造２階建，入母屋造，瓦葺で，鉄板葺の下屋をまわす。間口は１１間半，１階は湯治部屋を中心とし，２階正面道路側に上客客室を配する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001853"},{"id":"00001854","register_sub_id":"101","register_pk":"102844","name":"ゆさや旅館土蔵","kana":"ゆさやりょかんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"宮城県","address":"宮城県大崎市鳴子温泉字湯元74-2、74-3","lat":38.74187731,"lng":140.71794821,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造2階建、瓦葺、建築面積35㎡","structure_material":"木造2階建","registered":"2000.10.18(平成12.10.18)","register_no":"04 － 0031","desc":"本館の道路を隔てた向かいの敷地奥に位置する。桁行３間半，梁行２間半規模の切妻造，妻入の蔵で，北西面の妻面に片流れの下屋を付けて蔵前とする。腰を人造石洗出し，石目地仕上げとし，開口部はアーチ型とする。構造は「木筋コンクリート」とされる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001854"},{"id":"00002598","register_sub_id":"101","register_pk":"103588","name":"勇駒酒造本社店舗","kana":"いさみごましゅぞうほんしゃてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市増田町増田字中町64","lat":39.20354338,"lng":140.54599736,"geo_status":"db","era":"大正末期／昭和10代増築","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"木造2階建、鉄板葺、建築面積104㎡","structure_material":"木造2階建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0086","desc":"増田町の中心部，街道沿いにある。東西に細長い敷地で，店舗はその東に建つ。入母屋造の２階建で，正面となる東面に平屋建で看板建築の店舗を設ける。看板部分はセメントモルタルで酒樽を模した鏝絵を描き，商家の並ぶ町並の中で存在感がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002598"},{"id":"00007719","register_sub_id":"101","register_pk":"108701","name":"石直商店店舗兼主屋","kana":"いしなおしょうてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字七日町122","lat":39.20238448,"lng":140.54653011,"geo_status":"db","era":"明治前期／昭和43改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造2階建、鉄板葺、建築面積258㎡","structure_material":"木造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"05-0168","desc":"通りの東に占める短冊状の敷地の西端に建つ。切妻造妻入鉄板葺で、正面は白漆喰壁に束や梁をあらわす。正面側を店舗とし、通り土間を付ける居室を奥に配する。店舗２階は舟底状の天井を張る座敷で、トコや付書院を構え、通り側に縁を設ける。商家の構えをよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007719"},{"id":"00007720","register_sub_id":"101","register_pk":"108702","name":"石直商店文庫蔵","kana":"いしなおしょうてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字七日町122","lat":39.20244404,"lng":140.547013,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積39㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"05-0169","desc":"敷地の中央に東西棟で建つ。桁行７．３ｍ梁間４．６ｍの土蔵造２階建、置屋根の切妻造妻入鉄板葺とする。外壁は白漆喰仕上げで、腰に下見板を張る。西面の入口には片引戸をたてる。小屋組は梁上に束と小梁で地棟を支持し、密に垂木を配る。丁寧に造られた土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007720"},{"id":"00012467","register_sub_id":"101","register_pk":"367762","name":"今野商店土蔵","kana":"いまのしょうてんどぞう","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市大森町字大森175","lat":39.343822,"lng":140.427719,"geo_status":"geocoded","era":"明治43年／大正15年･昭和47年頃改修","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"土蔵造一部煉瓦造2階建、金属板葺、建築面積39㎡","structure_material":"土蔵造一部煉瓦造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"05 － 0219","desc":"店蔵背面に接し、東の街路に面して建つ。土蔵造二階建、切妻造妻入で、南側面と一階正面南半の壁は煉瓦造の現しとする。正面は白漆喰塗を基調としつつ、破風と円弧状の窓庇を黒漆喰塗として表構えを引締める。店蔵と同じく街路沿いの歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012467"},{"id":"00012466","register_sub_id":"101","register_pk":"367761","name":"今野商店店蔵","kana":"いまのしょうてんみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市大森町字大森175","lat":39.31374139,"lng":140.56669444,"geo_status":"db","era":"大正15年／昭和47年頃・平成28年改修","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、金属板葺、建築面積63㎡","structure_material":"土蔵造2階建","registered":"2018.11.02(平成30.11.02)","register_no":"05 － 0218","desc":"大森町にある商家で、店蔵は敷地東北隅に北面して建つ。土蔵造二階建で、切妻屋根を矩折れにかける。一階は正面を石造風とし、東側面に下屋を付す。内部は店舗空間を広く取り、中央部に吹抜けを設ける。市街中心部の角地にあって歴史的景観の核をなしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012466"},{"id":"00001033","register_sub_id":"101","register_pk":"102023","name":"木村屋商店本店","kana":"きむらやしょうてんほんてん","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市大町5-23","lat":39.31514555,"lng":140.56823892,"geo_status":"db","era":"明治37頃","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"土蔵造２階建，鉄板葺，建築面積35㎡","structure_material":"土蔵造２階建","registered":"1999.02.17(平成11.02.17)","register_no":"05 － 0046","desc":"旧羽州街道沿い，横手市街の藩政期以降に栄えた商業地に位置し，旅館「平利」・「平源」旅館の向いに建つ。明治３５・３６年の大火の教訓から蔵造りとした店舗建築で，２階に重厚な防火戸を付ける。羽州街道の町並みを知る上で貴重な遺構のひとつになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001033"},{"id":"00008245","register_sub_id":"101","register_pk":"133887","name":"旧石宇商店座敷蔵","kana":"きゅういしうしょうてんざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県横手市増田町増田字七日町140","lat":39.20329473,"lng":140.54564607,"geo_status":"db","era":"昭和8年","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積101㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0181","desc":"短冊状の敷地の中央、東西棟で建つ。桁行９．１ｍ梁間４．２ｍの２階建土蔵。置屋根で周囲に鞘を設ける。切石積基礎上、漆喰仕上げとし、腰などを黒漆喰とする。１階は前後二室に分け、奥の座敷にはトコなどを構える。地区内において掉尾に位置する座敷蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008245"},{"id":"00008243","register_sub_id":"101","register_pk":"133885","name":"旧栄助商店座敷蔵","kana":"きゅうえいすけしょうてんざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県横手市増田町増田字七日町154-2他","lat":39.20212833,"lng":140.54613894,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、鉄板葺、建築面積116㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0179","desc":"通りに東面する短冊形の敷地中央に位置する。桁行９．１ｍ梁間５．６ｍの切妻造妻入で、鉄板葺の置屋根とし、周囲に鞘を設ける。切石積基礎上に建ち、漆喰仕上げで、腰や開口部などを黒漆喰とする。伝統的な架構を用いており、当地における標準的な座敷蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008243"},{"id":"00001833","register_sub_id":"101","register_pk":"102823","name":"旧大島商会店舗","kana":"きゅうおおしましょうかいてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市大町一丁目8-2","lat":39.71937222,"lng":140.11811944,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"煉瓦造2階建、鉄板葺、建築面積73㎡","structure_material":"煉瓦造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"05 － 0066","desc":"秋田市内最初期の煉瓦造建築で，両側面及び背面に控壁を設ける。基礎と建物四隅，及びアーチ型の開口部廻りに積んだ切石の白さが赤煉瓦壁に映える。高級雑貨等を販売した県内最初の百貨店として建設されたもので，１階正面中央のアーチ型の広い出入口に特色。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001833"},{"id":"00013493","register_sub_id":"101","register_pk":"504858","name":"旧加藤茶舗店蔵","kana":"きゅうかとうちゃほみせぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県横手市十文字町字曙町7-3","lat":39.22172778,"lng":140.52425,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、鉄板葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"05 － 0234","desc":"吉乃鉱山の物資運搬拠点として発展した十文字に所在。二階建切妻造平入で一間幅の下屋を設ける。一階は四間幅の間口いっぱいを開口とした開放的な構えとし、二階は引込戸の窓を開ける。一階は一室として柱を密に立てる。地域のランドマーク的存在の店舗。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013493"},{"id":"00007715","register_sub_id":"101","register_pk":"108697","name":"旧佐々虎呉服店（佐々木家住宅）資材蔵","kana":"きゅうささとらごふくてんしざいぐら（ささきけじゅうたく）","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字中町91","lat":39.20464875,"lng":140.54663574,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積111㎡","structure_material":"土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"05 - 0164","desc":"座敷蔵の東南に東西棟で建つ。桁行１２ｍ梁間５．２ｍの土蔵造２階建で、切妻造鉄板葺の置屋根とする。白漆喰仕上げで、西正面には掛子塗の両開戸を構え、上部に鏝絵の家紋を飾る。内部は板敷で、１、２階とも二室に間仕切る。増田地区における最大規模の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007715"},{"id":"00007713","register_sub_id":"101","register_pk":"108695","name":"旧佐々虎呉服店（佐々木家住宅）主屋及び座敷蔵","kana":"きゅうささとらごふくてんしゅおくおよびざしきくら（ささきけじゅうたく）","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県横手市増田町増田字中町91","lat":39.20466606,"lng":140.54622351,"geo_status":"db","era":"昭和15・明治17","year":1940,"year_source":"db","year_min":1940,"year_max":1940,"year_label":null,"structure":"木造一部土蔵造2階建、鉄板葺、建築面積199㎡","structure_material":"木造一部土蔵造2階建","registered":"2009.08.07(平成21.08.07)","register_no":"05 - 0162","desc":"主屋と座敷蔵が東西に連続して建つ。主屋は切妻造の木造２階建。南面に吹抜けの廊下を設け、北側には１、２階とも二室を配し、数寄屋風意匠になる接客用座敷とする。座敷蔵は大規模な土蔵造２階建、主屋側は黒漆喰磨仕上げで、角に施された白漆喰の線が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007713"},{"id":"00007718","register_sub_id":"101","register_pk":"108700","name":"旧佐藤三十郎商店店舗兼主屋及び座敷蔵","kana":"きゅうさとうさんじゅうろうしょうてんてんぽけんしゅおくおよびざしきくら","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字七日町147","lat":39.20277144,"lng":140.54598212,"geo_status":"db","era":"明治20・明治11／大正期・昭和50頃改修","year":1887,"year_source":"db","year_min":1887,"year_max":1887,"year_label":null,"structure":"木造一部土蔵造平屋一部2階建、鉄板葺、建築面積385㎡","structure_material":"木造一部土蔵造平屋一部2階建","registered":"2009.08.07(平成21.08.07)","register_no":"05-0167","desc":"東面する切妻造妻入の店舗兼主屋と、その西の座敷蔵が連続して建ち、南に通り土間を設ける。正面は白漆喰壁に短い束と梁の伝統的構え。座敷蔵は１階西寄りを南北二室に間仕切り、南に座敷、北に納戸を配する。座敷は漆塗とし、凝った造りの浅いトコを構える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007718"},{"id":"00007838","register_sub_id":"101","register_pk":"108819","name":"旧清水肉店店舗兼主屋","kana":"きゅうしみずにくてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県横手市増田町増田字本町76","lat":39.2049405,"lng":140.54456729,"geo_status":"db","era":"昭和8／昭和51・平成10改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積154㎡","structure_material":"木造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"05 - 0173","desc":"南北に細長い敷地に南寄りに建つ。 桁行１９ｍ梁間８．２ｍの木造２階建、南北棟の切妻造鉄板葺。南妻面は、螻羽が深く、小屋組を現す白漆喰仕上げとし、庇に吹寄垂木と疎垂木を併用。内部は一部を吹抜けとする通り土間を南側に設ける。積雪地らしい町家建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007838"},{"id":"00005539","register_sub_id":"101","register_pk":"106527","name":"旧関善酒店主屋","kana":"きゅうせきぜんしゅてんおもや","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県鹿角市花輪字上花輪85","lat":40.185196,"lng":140.789032,"geo_status":"db","era":"明治38","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"木造平屋一部2階建、鉄板葺、建築面積590㎡","structure_material":"木造平屋一部2階建","registered":"2006.08.03(平成18.08.03)","register_no":"05 － 0146","desc":"県道に西面して建つ。桁行１４間，梁間１１間の規模で，木造平屋一部２階建，切妻造，鉄板葺，平入とし，正面にこみせを設ける。北側を床上部とし，表側に店土間をとり，通り土間を通す。通り土間上部の架構は見事で，全体に技術，規模，意匠共に秀でる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005539"},{"id":"00008246","register_sub_id":"101","register_pk":"133888","name":"旧長江八兵衛商店座敷蔵","kana":"きゅうながえはちべえしょうてんざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県横手市増田町増田字中町66","lat":39.20367931,"lng":140.54565786,"geo_status":"db","era":"弘化4年(1847)","year":1847,"year_source":"db","year_min":1847,"year_max":1847,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積152㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0182","desc":"東西に細長い敷地の中央に東西棟で建つ妻入の２階建土蔵。桁行１５ｍ梁間５．９ｍで、切妻造鉄板葺の鞘を設ける。外観は黒漆喰と白漆喰を塗り分ける。１階西寄りに畳敷の居室を間仕切り、トコやトコ脇を構え、柱を漆塗とする。梁組など古風な仕様を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008246"},{"id":"00007836","register_sub_id":"101","register_pk":"108817","name":"旧長江八兵衛商店味噌蔵","kana":"きゅうながえはちべえしょうてんみそぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字中町66","lat":39.20368554,"lng":140.54529245,"geo_status":"db","era":"明治前期／大正期改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、金属板葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"05-0171","desc":"東と北に接道し、東西に細長い敷地の西端に建つ。桁行８．２ｍ梁間５．５ｍの土蔵造２階建で、東西棟の切妻造金属板葺。東妻面にトマエを付し、掛子塗三段の土扉を中心からずらして吊る。内部は１、２階とも一室。当地域における古い形式の小屋架構を残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007836"},{"id":"00004897","register_sub_id":"101","register_pk":"105887","name":"國萬歳酒造主屋","kana":"くにばんざいしゅぞうしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県秋田市新屋元町142他","lat":39.68418176,"lng":140.08396517,"geo_status":"db","era":"大正4","year":1915,"year_source":"db","year_min":1915,"year_max":1915,"year_label":null,"structure":"木造2階一部平屋建、鋼板葺、建築面積270㎡","structure_material":"木造2階一部平屋建","registered":"2005.11.10(平成17.11.10)","register_no":"05 － 0123","desc":"市街地南部の雄物川左岸，旧羽州浜街道沿いに位置する。間口３間半，寄棟造，妻入の木造２階建で，正面に張出す庇の中央に切妻の玄関を設ける。内部は，通り土間に沿って帳場及びオエを配する。醸造業が盛んな新屋地区の歴史的街路景観の構成要素。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004897"},{"id":"00007716","register_sub_id":"101","register_pk":"108698","name":"興文館東海林書店店舗兼主屋及び座敷蔵","kana":"こうぶんかんしょうじしょてんてんぽけんしゅおくおよびざしきくら","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町増田字中町100","lat":39.20382196,"lng":140.54637551,"geo_status":"db","era":"明治前期・明治2／大正2改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造一部土蔵造2階一部平屋建、鉄板葺、建築面積459㎡","structure_material":"木造一部土蔵造2階一部平屋建","registered":"2009.08.07(平成21.08.07)","register_no":"05 - 0165","desc":"通りに西面して、店舗兼主屋、座敷蔵が東西に連続して建つ。正面に入母屋造２階建を配し、その東に三段に棟高が異なる切妻屋根が続く。主屋は南の庭園側に明るく開放的な通り土間を設け、北に居室を配する。座敷蔵は増田地区における古い座敷蔵のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007716"},{"id":"00008242","register_sub_id":"101","register_pk":"133884","name":"佐々平商店文庫蔵","kana":"ささへいしょうてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"江戸","pref":"秋田県","address":"秋田県横手市増田町増田字中町96","lat":39.20414373,"lng":140.54640858,"geo_status":"db","era":"文久4年(1864)／大正6年改修","year":1864,"year_source":"db","year_min":1864,"year_max":1864,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積114㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0178","desc":"東西に長い敷地に東西棟で建つ。桁行１１ｍ梁間５．４ｍ、妻入の２階建土蔵で、鉄板葺の鞘を設ける。西面の出入口を黒漆喰、他を白漆喰で仕上げる。束を建て鳥居型とする二重梁を妻面に、梁上に小梁二段を重ねる三重梁を中間に置き棟木を支持する古い架構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008242"},{"id":"00007837","register_sub_id":"101","register_pk":"108818","name":"佐藤養助漆蔵資料館旧米蔵","kana":"さとうようすけうるしぐらしりょうかんきゅうこめぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県横手市増田町増田字本町5他","lat":39.20536749,"lng":140.54533367,"geo_status":"db","era":"大正後期／平成13改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階建、鉄板葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2009.11.02(平成21.11.02)","register_no":"05-0172","desc":"南北に長い矩形敷地の北東に建つ。桁行７．３ｍ梁間５．５ｍの土蔵造２階建、切妻造鉄板葺。南妻に主たる出入口を穿ち、黒漆喰仕上げとし、角に白漆喰を配し、冠木中央には「龍」の字を鏝細工で飾る。掛子塗三段の両開扉を吊る。丁寧に仕上げられた土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007837"},{"id":"00001832","register_sub_id":"101","register_pk":"102822","name":"高砂堂店舗","kana":"たかさごどうてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"店舗","type_guess_confidence":"high","period":"大正","pref":"秋田県","address":"秋田県秋田市保戸野通町2-24","lat":39.72065599,"lng":140.118591,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積64㎡","structure_material":"木造2階建","registered":"2000.09.26(平成12.09.26)","register_no":"05 － 0065","desc":"商店街の角地に建つ木造２階建，寄棟造の店舗。街路側二面に庇を設ける。白漆喰塗籠，瓦葺の和風の外観とするが，内部は洋風とし一階床に男鹿石，ショーケース台に大理石や瑪瑙を用いる。設計・施工は大工藤本東三郎。平成７年，道路拡幅に伴い後方に曳屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001832"},{"id":"00008244","register_sub_id":"101","register_pk":"133886","name":"髙橋茶舗座敷蔵","kana":"たかはしさほざしきぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"秋田県","address":"秋田県横手市増田町増田字七日町151","lat":39.20234667,"lng":140.54605127,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積171㎡","structure_material":"土蔵造2階建","registered":"2010.09.10(平成22.09.10)","register_no":"05 － 0180","desc":"東西に細長い敷地の中央に東西棟で建つ。桁行１１ｍ梁間６．４ｍの２階建土蔵、切妻造の置屋根とし、周囲に鞘を設ける。切石積基礎上、全体を黒漆喰仕上げとし、細く白漆喰で角など輪郭を縁取る。１階内部はもとは三室に間仕切られ、透かし彫りの欄間が残る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008244"},{"id":"00007952","register_sub_id":"101","register_pk":"128785","name":"鶴の湯温泉本陣","kana":"つるのゆおんせんほんじん","category":"産業3次","subcategory":"建築物","type_guess":"旅館","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県仙北市田沢湖田沢字湯ノ岱2番地先先達沢国有林生保内事業区50林班ハ小班","lat":39.80515018,"lng":140.77966356,"geo_status":"db","era":"明治前期／昭和後期・平成10頃改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、茅葺、建築面積225㎡","structure_material":"木造平屋建","registered":"2010.01.15(平成22.01.15)","register_no":"05-0174","desc":"東西４３ｍと桁行に長い建物で、寄棟造茅葺とし、南面に煙出を設ける。西半部は入口土間と十一畳からなる客室五室を並べ、東半部には休憩室や事務室などを配する。外壁は竪板張とし、内部には釿仕上げの梁を架け渡す。風趣に富む湯治場の雰囲気をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007952"},{"id":"00003496","register_sub_id":"101","register_pk":"104486","name":"十和田ホテル本館","kana":"とわだほてるほんかん","category":"産業3次","subcategory":"建築物","type_guess":"ホテル","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県鹿角郡小坂町十和田湖字鉛山","lat":40.43953794,"lng":140.84358214,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造一部鉄筋コンクリート造3階建、鋼板葺、建築面積780㎡","structure_material":"木造一部鉄筋コンクリート造3階建","registered":"2003.09.19(平成15.09.19)","register_no":"05 － 0094","desc":"十和田八幡平国立公園内の湖畔高台に築かれた県営ホテル。Ｌ字形平面で、外装全体に秋田杉を用い，石積基壇上に半割の丸太を配すのが特徴。内部は，玄関吹抜や銘木を用いた巧妙な意匠の室内など見所が多い。昭和前期の大規模木造建築の好例。設計は長倉謙介。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003496"},{"id":"00009878","register_sub_id":"101","register_pk":"196025","name":"那波紙店五号倉庫","kana":"なばかみてんごごうそうこ","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"秋田県","address":"秋田県秋田市大町5-249-11","lat":39.71505378,"lng":140.11400615,"geo_status":"db","era":"昭和13","year":1938,"year_source":"db","year_min":1938,"year_max":1938,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積111㎡","structure_material":"木造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0199","desc":"店舗兼主屋の斜向かいの敷地に東西棟で建つ。木造二階建、桁行一四・六メートル梁間七・六メートル、切妻造鉄板葺で小屋はキングポストトラスを組む。外壁はモルタル塗で、正面となる東妻は洗出し仕上げとし、妻壁を立ち上げ、柱形を表すなど意匠を凝らす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009878"},{"id":"00009876","register_sub_id":"101","register_pk":"196023","name":"那波紙店商品蔵","kana":"なばかみてんしょうひんぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市大町4-219他","lat":39.7152667,"lng":140.11476504,"geo_status":"db","era":"明治30","year":1897,"year_source":"db","year_min":1897,"year_max":1897,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積157㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0197","desc":"店舗兼主屋の後方南寄りに東西棟で建つ。土蔵造二階建、桁行一一メートル梁間六・七メートルで、並び建つ文庫蔵とともに鞘屋根を一連に架けて、主屋と一体的な空間構成とする。二重梁の上に舟肘木状の材を直交させて棟木を受ける小屋組に、地方的特色を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009876"},{"id":"00009874","register_sub_id":"101","register_pk":"196021","name":"那波紙店店舗兼主屋","kana":"なばかみてんてんぽけんしゅおく","category":"産業3次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市大町4-219他","lat":39.71531667,"lng":140.11453661,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造平屋一部2階建、鉄板葺、建築面積463㎡","structure_material":"木造平屋一部2階建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0195","desc":"久保田城の南西方敷地に西面して建つ。切妻造妻入鉄板葺で、南西面に下屋を廻らし、妻壁の梁や束を化粧で現す。南側に通す土間沿いにオエや台所を並べ、奥寄りの仏間や座敷を鍵型に張出す。コミセの名残をとどめる間取りや妻壁意匠に当地の町家の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009874"},{"id":"00009875","register_sub_id":"101","register_pk":"196022","name":"那波紙店文庫蔵","kana":"なばかみてんぶんこぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"秋田県","address":"秋田県秋田市大町4-219他","lat":39.71533094,"lng":140.11477932,"geo_status":"db","era":"明治中期／明治41移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鋼板葺、建築面積106㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0196","desc":"店舗兼主屋の後方北寄りに東西棟で建つ。土蔵造二階建、桁行七・三メートル梁間五・二メートルで、置屋根式の屋根を主屋の屋根と一連とし、内蔵形式とする。外壁漆喰塗で鉢巻を廻らし、西面の戸口に上質な掛子塗の扉を吊り、要所を黒漆喰塗で引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009875"},{"id":"00009877","register_sub_id":"101","register_pk":"196024","name":"那波紙店向かい蔵","kana":"なばかみてんむかいぐら","category":"産業3次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県秋田市大町5-201-2","lat":39.71510613,"lng":140.11472475,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鋼板葺、建築面積70㎡","structure_material":"土蔵造2階建","registered":"2014.04.25(平成26.04.25)","register_no":"05 － 0198","desc":"商品蔵と通りを挟む敷地に東西棟で建つ切妻造で、桁行九・七メートル梁間五メートル、土蔵造二階建である。西妻を戸口として下屋を設け、南面に窓を設ける。外壁は漆喰塗で腰を簓子下見板張とする。小屋組は、商品蔵に似て、二重梁で棟木を支持する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009877"},{"id":"00002591","register_sub_id":"101","register_pk":"103581","name":"日の丸醸造本社店舗","kana":"ひのまるじょうぞうほんしゃてんぽ","category":"産業3次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"秋田県","address":"秋田県横手市増田町七日町114-2","lat":39.2020569,"lng":140.54656071,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、鉄板葺、建築面積163㎡","structure_material":"木造平屋建","registered":"2002.02.14(平成14.02.14)","register_no":"05 － 0079","desc":"増田町の中心部にあり，街道に西面して建つ平屋建の店舗建築。切妻造・鉄板葺で，妻入とする。通りに面した妻面は４重の化粧梁を見せ，地棟を突出させて，下屋庇を葺き下ろした構成になり，緩勾配の屋根と相俟って，当地方の妻入町家の形態をよく伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002591"}];
